// ── Agents panel: find and filter, mirroring the Diamonds rail ──────────
// A flat list with chips, deliberately not a Diamond→children tree: the
// tree's height is more than the dock can spare, and the parent a run
// belongs to already rides on the run, as a chip.

/// The Diamond a run belongs to, looked up live, or null.
function agentDiamondOf(run) {
	if (!run || !run.diamondId) return null;
	for (var i = 0; i < pg.diamonds.length; i++) if (pg.diamonds[i].id === run.diamondId) return pg.diamonds[i];
	return null;
}

/// A run's tags: the tags of the Diamond that started it. A worker has none
/// of its own, so it borrows its Diamond's -- which is what lets one tag
/// vocabulary filter both rails.
export function agentTagsOf(run) {
	return tagsOf(agentDiamondOf(run));
}

/// The chat a run was dispatched from, looked up live, or null.
function agentChatOf(run) {
	if (!run || !run.chatId) return null;
	for (var i = 0; i < pg.chats.length; i++) if (pg.chats[i].id === run.chatId) return pg.chats[i];
	return null;
}

/// The name the USER gave that chat, or '' when they never gave it one.
///
/// The live chat wins over the run's snapshot, which was taken at dispatch and
/// does not follow a rename; the snapshot is all that is left once the chat
/// itself has gone to the trash.
function agentChatName(run) {
	var s = agentChatOf(run);
	if (s) return s.name || '';
	return (run && run.chatName) || '';
}

/// What to call that chat where a chip has to name it.
///
/// `chatDisplayName` and nothing of its own, so the rail and the chip call one
/// conversation by one phrase -- the user's name for it, or "the chat from
/// 09:12". Seq 115 deleted default chat names, and until this the chip fell
/// through to the placeholder: every chat tile read "a chat", which is the one
/// case the chip exists for, two conversations' agents running at once.
function agentChatLabel(run) {
	var s = agentChatOf(run);
	if (s) return chatDisplayName(s);
	return (run && run.chatName) || tOr('agents.from_chat', 'a chat');
}

/// One chip on a run's tile: names where the run came from, and filters to it.
///
/// "Where from" is a Diamond for a dispatched run and a CHAT for one an
/// ordinary conversation sent. Both filter. The chat half did not: the chip was
/// drawn, the comment said it filtered, and the listener was still hung on
/// `run.diamondId` -- which a chat-dispatched run does not have -- so every
/// chat chip was inert from the day it was added.
export function agentDiamondChip(run) {
	var el = document.createElement('button');
	// Which filter this chip is the subject of depends on which end the run
	// hangs off. A chat-dispatched run has no `diamondId` at all, so the
	// Diamond comparison can never mark it active.
	var on = run.diamondId
		? (pg.agentDiamondFilter === run.diamondId)
		: (!!run.chatId && pg.agentChatFilter === run.chatId);
	el.className = 'tag-chip diamond-chip' + (on ? ' tag-active' : '');
	// A chat-dispatched run says which CONVERSATION sent it. The chip existed with
	// a Diamond-less branch before anything could reach it, and that branch says
	// only "not from a Diamond" -- true, and no help at all when two chats have
	// agents running at once. A name is what tells them apart.
	//
	// The hue is keyed to the chat's ID rather than to what the chip says. Names
	// are optional and now usually absent, and hashing the empty string handed
	// every unnamed chat the same colour -- the second way two conversations
	// became one. An id is per chat and never changes under a rename.
	var chat = run.chatId ? agentChatOf(run) : null;
	var given = run.chatId ? agentChatName(run) : '';
	el.style.setProperty('--tag-h', tagHue(run.diamondName || run.chatId || ''));
	el.textContent = '↳ ' + (run.diamondName
		|| (run.chatId ? agentChatLabel(run) : t('agents.no_diamond')));
	// The title says where the run came from AND what pressing the chip does.
	// Provenance alone left a button whose only description was a fact about
	// the past, which is how a control comes to look like a label.
	var acts = ' ' + t('agents.only_from_chat');
	if (run.diamondId) {
		el.title = t('agents.only_from', { name: run.diamondName });
	} else if (given) {
		el.title = tOr('agents.from_chat_help', 'Sent from the chat “{name}”.', { name: given }) + acts;
	} else if (chat) {
		// A derived phrase is a description, and the named key puts quotation marks
		// round it -- "the chat 'a chat'". This one says the same thing without
		// dressing a description as a name, and adds the one fact the chip's own
		// short label leaves out.
		el.title = tOr('agents.from_chat_help_when', 'Sent from a chat you have not named, last used {when}.',
			{ when: tileWhen(chat.updatedAt || Date.now()) }) + acts;
	} else if (!run.chatId) {
		el.title = t('agents.no_diamond_help');
	} else {
		// The chat has gone to the trash: there is no name to quote and no time
		// left to read, so the title is what the chip DOES and nothing else. It
		// used to be left blank, which is defensible for a label and not for a
		// button.
		el.title = t('agents.only_from_chat');
	}
	if (run.diamondId) {
		el.addEventListener('click', function (e) { e.stopPropagation(); setAgentDiamondFilter(run.diamondId); });
	} else if (run.chatId) {
		el.addEventListener('click', function (e) { e.stopPropagation(); setAgentChatFilter(run.chatId); });
	}
	return el;
}

/// Does a run survive the agents search box and its filter chip? Name,
/// task, Diamond name, model and inherited tags are searched.
export function agentMatches(run) {
	if (pg.agentDiamondFilter && run.diamondId !== pg.agentDiamondFilter) return false;
	if (pg.agentChatFilter && run.chatId !== pg.agentChatFilter) return false;
	if (pg.agentTagFilter && agentTagsOf(run).indexOf(pg.agentTagFilter) === -1) return false;
	if (!pg.agentQuery) return true;
	// The chat's name is searchable beside the Diamond's: it is the only word on a
	// chat-dispatched tile that says where the run came from, and a panel holding
	// two conversations' fan-outs is exactly when somebody types a name into the box.
	// Its LIVE name, so a chat renamed after it dispatched answers to what it is
	// called now. The chip's derived phrase is deliberately NOT searched: it is a
	// description every unnamed chat shares, so "chat" would match all of them and
	// match nothing in particular -- and a relative time moves under the query.
	var hay = [run.name, run.task, run.diamondName, agentChatName(run), run.model || '',
		run.model ? shortModel(run.model, run.provider) : '']
		.concat(agentTagsOf(run)).join(' ').toLowerCase();
	return hay.indexOf(pg.agentQuery) !== -1;
}

/// Filter the panel to one Diamond (toggles off if it is already the filter).
function setAgentDiamondFilter(diamondId) {
	pg.agentDiamondFilter = (pg.agentDiamondFilter === diamondId) ? null : diamondId;
	pg.agentChatFilter = null;  // one filter at a time, as the rail has one
	pg.agentTagFilter = null;
	Workers.render();
}

/// Filter the panel to one chat (toggles off if it is already the filter).
function setAgentChatFilter(chatId) {
	pg.agentChatFilter = (pg.agentChatFilter === chatId) ? null : chatId;
	pg.agentDiamondFilter = null;
	pg.agentTagFilter = null;
	Workers.render();
}

/// Filter the panel to one tag (toggles off if it is already the filter).
export function setAgentTagFilter(tag) {
	pg.agentTagFilter = (pg.agentTagFilter === tag) ? null : tag;
	pg.agentDiamondFilter = null;
	pg.agentChatFilter = null;
	Workers.render();
}

// ── Agents panel: the grid above, the pinned tiles below (D-20261015-10) ──

/// The live questions runs have parked on the Pending panel, by run id. Only a
/// question this tab can still answer counts: an expired one is the record of a
/// question nobody is waiting on any more, and amber for it would be a false alarm.
export function agentWaiting() {
	var out = {};
	(Pending.items || []).forEach(function (it) {
		if (it && it.kind === 'consent' && it.runId && !it.expired) out[it.runId] = it;
	});
	return out;
}

/// The question one run is waiting on, or null.
export function agentAsk(run) {
	return agentWaiting()[String(run && run.id)] || null;
}

/// Pin a run's tile below the grid, or take it away. Only a press calls this.
export function setAgentPinned(id, on) {
	id = String(id);
	var has = pg.agentPins.indexOf(id) !== -1;
	if (!!on === has) return;
	pg.agentPins = DaimondAgentGrid.togglePin(pg.agentPins, id);
	// ONE TILE, not the panel. A press adds or takes away its own tile and turns its
	// own square; redrawing everything per press made pressing 80 squares 80 whole
	// renders, a second-long freeze (verify_worker_render). A press the panel cannot
	// do in place -- no list drawn yet, or a run that is not there -- falls back to it.
	if (!agentPinInPlace(id, on)) Workers.render();
	// A tile just opened is scrolled into view: on a phone the lower half is a
	// sheet, and a tile opened past its edge would look like a press that did nothing.
	// Once a frame, for the last press: scrolling forces a layout, and a layout per
	// press made pressing many squares at once a layout of the whole list each time.
	if (on) {
		var first = !agentPinScrollTo;
		agentPinScrollTo = id;
		if (first) requestAnimationFrame(function () {
			var want = agentPinScrollTo;
			agentPinScrollTo = '';
			var c = agentsList && agentsList.querySelector('.acard[data-run="' + want + '"]');
			if (c && c.scrollIntoView) c.scrollIntoView({ block: 'nearest', inline: 'nearest' });
		});
	}
}
// page-split: install 108

/// Apply one press to what is drawn: the square's pressed state, the tile added at
/// the end of the lower half (pin order) or taken out of it, and the list's key, so
/// the next frame does not mistake the new pin set for a changed list. Answers false
/// when it could not, and the caller redraws.
function agentPinInPlace(id, on) {
	if (!agentsList || !Workers._drawn || Workers._listKey == null) return false;
	var run = Workers.runs.find(function (r) { return String(r.id) === id; });
	if (on && !run) return false;
	var sq = agentsGrid && agentsGrid.querySelector('.agsq[data-run="' + id + '"]');
	if (sq) {
		sq.classList.toggle('pin', !!on);
		sq.setAttribute('aria-pressed', on ? 'true' : 'false');
	}
	var old = Workers._drawn[id];
	if (on) {
		var card = Workers.tile(run);
		card._agKey = Workers.runKey(run, agentWaiting());
		Workers._drawn[id] = card;
		var cut = agentsList.querySelector('.agents-dropped');
		agentsList.insertBefore(card, cut || null);
	} else {
		if (old && old.parentNode) old.parentNode.removeChild(old);
		delete Workers._drawn[id];
	}
	agentsList.classList.toggle('has-pins', pg.agentPins.length > 0);
	agentSheetDots();
	Workers._listKey = Workers.listKey();
	return true;
}

/// The phone sheet's dots: one per pinned tile when there are two or more, the one
/// in view lit. The list scrolls sideways there (CSS scroll-snap, <=760px); on a
/// desktop the dots are hidden and the tiles stack.
export function agentSheetDots() {
	var dots = document.getElementById('agents-dots');
	var sheet = document.getElementById('agents-sheet');
	if (sheet) sheet.classList.toggle('has-pins', pg.agentPins.length > 0);
	if (!dots || !agentsList) return;
	dots.innerHTML = '';
	if (pg.agentPins.length < 2) return;
	pg.agentPins.forEach(function () { dots.appendChild(document.createElement('i')); });
	// Lit in the next frame: which dot is in view reads the list's width, a layout,
	// and a layout per press is what made pressing many squares at once slow.
	if (!agentDotFrame) agentDotFrame = requestAnimationFrame(function () {
		agentDotFrame = 0;
		agentSheetDotOn();
	});
	if (!agentsList._dotsBound) {
		agentsList._dotsBound = true;
		agentsList.addEventListener('scroll', agentSheetDotOn, { passive: true });
	}
}
// page-split: install 109
function agentSheetDotOn() {
	var dots = document.getElementById('agents-dots');
	if (!dots || !agentsList) return;
	var w = agentsList.clientWidth || 1;
	var at = Math.round(agentsList.scrollLeft / w);
	Array.prototype.forEach.call(dots.children, function (d, i) { d.classList.toggle('on', i === at); });
}

/// What the grid calls a row's origin: the Diamond, or the chat that sent it.
function agentOriginName(run) {
	return run.diamondName || (run.chatId ? agentChatLabel(run) : t('agents.no_diamond'));
}

/// Open the thread a run came from -- its Diamond's conversation, or the chat that sent it --
/// and, on a phone, put that conversation on screen (think pass: the diamond is pressable).
function agentOpenThread(run) {
	var th = DaimondAgentGrid.threadOf(run);
	if (!th) return;
	if (th.kind === 'diamond') {
		var f = (pg.diamonds || []).find(function (x) { return x.id === th.id; });
		if (!f) { toast(t('pending.diamond_gone'), true); return; }
		selectDiamond(f, 'chat');
	} else {
		var c = agentChatOf(run);
		if (!c) return;
		selectChat(c);
	}
	if (isPhoneViewport()) mshow('ai');
}

/// A row's diamond -- the thread (first) or a later orchestrating turn (`nested`): a button
/// that opens the thread, or a mark alone when there is no thread left to open.
function agentThreadDiamond(cls, run, label) {
	var th = DaimondAgentGrid.threadOf(run);
	var o = document.createElement(th ? 'button' : 'span');
	o.className = 'agsq o ' + cls;
	o.title = label;
	if (th) {
		o.type = 'button';
		o.setAttribute('aria-label', tOr('agents.open_thread', 'Open {name}', { name: label }));
		o.addEventListener('click', function () { agentOpenThread(run); });
	} else o.setAttribute('aria-hidden', 'true');
	return o;
}

/// What a run has used: `{ pt, ct, ca, toks, usd, est, spent }`. `usd` is the provider's own
/// figure, `est` the price table's (`DaimondPricing.priceFor`) only where the provider stated
/// none, and `spent` the one figure the tile's tag, its meter and the square all read
/// (AGENT-GRID lead decision, r569). A run that was mostly cache hits costs a fraction of
/// what the table says, so the table is never preferred over a stated cost.
///
/// A running worker reads the live counters, NOT prompt_tokens: that getter borrows the
/// session the running turn holds, so reading it would panic the engine; `cached_tokens`
/// and `cost_usd` borrow it too. Its stored cost is only written at a round's end, so the
/// square would otherwise sit still while it works.
export function agentRunSpend(run) {
	var pt = run.promptTokens || 0, ct = run.completionTokens || 0;
	var ca = run.cachedTokens || 0, usd = run.costUsd || 0;
	if (run.status === 'running' && run.app) {
		try {
			pt = (run.priorPrompt || 0) + (run.app.live_prompt_tokens || 0);
			ct = (run.priorCompletion || 0) + (run.app.live_completion_tokens || 0);
			ca = (run.priorCached || 0) + (run.app.live_cached_tokens || 0);
			usd = (run.priorCost || 0) + (run.app.live_cost_usd || 0);
		} catch (e) { /* engine busy: the stored figures stand */ }
	}
	var toks = pt + ct, est = null;
	if (toks && !(usd > 0) && window.DaimondPricing) {
		est = DaimondPricing.priceFor(run.model, pt, ct, ca, run.provider || '') || null;
	}
	var spent = usd > 0 ? usd : (est && est.usd > 0 ? est.usd : 0);
	return { pt: pt, ct: ct, ca: ca, toks: toks, usd: usd, est: est, spent: spent };
}

/// What a run's turn has spent against its cap (`DaimondAgentGrid.budget`), by the same
/// figure its tile shows (`agentRunSpend`).
export function agentBudget(run) {
	return DaimondAgentGrid.budget({ costUsd: agentRunSpend(run).spent, priorCost: run.priorCost || 0, capUsd: run.capUsd || 0 });
}

/// A running square's fill, bottom-up, by its turn's spend over its cap (mock .sq.run --f).
export function agentSquareFill(el, run) {
	var b = run.status === 'running' ? agentBudget(run) : null;
	var f = b ? Math.round(b.f * 1000) / 10 + '%' : '';
	if (f) el.style.setProperty('--f', f); else el.style.removeProperty('--f');
}

/// The grid: a row per origin, the origin's thread first as a small diamond, then a
/// square per run in start order. Colour is state; amber alone means "you". A search
/// or a filter DIMS what it leaves out rather than removing it, so no square moves
/// under the reader (think pass §1).
///
/// EVERY AGENT OF THE ACCOUNT: this device's runs and the peers' (`PeerAgents`), in the
/// same rows and lenses. A peer's square is read-only, so it is no button: its tile and
/// its controls are on the device that runs it.
export function renderAgentGrid() {
	if (!agentsGrid) return;
	var peerIds = {};
	var runs = Workers.runs.concat((PeerAgents ? PeerAgents.list() : []).map(function (r) { peerIds[r.id] = 1; return r; }));
	agentsGrid.innerHTML = '';
	if (!runs.length) {
		var empty = document.createElement('div');
		empty.className = 'agents-empty';
		empty.textContent = t('agents.none_yet');
		agentsGrid.appendChild(empty);
		return;
	}
	var wait = agentWaiting();
	var filtering = !!(pg.agentQuery || pg.agentDiamondFilter || pg.agentChatFilter || pg.agentTagFilter);
	agentsGrid.classList.toggle('dim', filtering);
	DaimondAgentGrid.LENSES.forEach(function (l) { agentsGrid.classList.toggle('lens-' + l, l === pg.agentLens); });
	/// A square's lens colour and the words for it: the colour is never the only telling.
	function lensDress(el, run) {
		var k = DaimondAgentGrid.lensPaint(pg.agentLens, run);
		if (!k) return '';
		el.style.setProperty('--k', k);
		if (pg.agentLens === 'cost') return (typeof SpendCap !== 'undefined' && SpendCap) ? SpendCap.money(run.costUsd || 0) : String(run.costUsd || 0);
		if (pg.agentLens === 'rating') return run.rating > 0 ? tOr('agents.rated_up', 'rated up')
			: run.rating < 0 ? tOr('agents.rated_down', 'rated down') : tOr('agents.unrated', 'unrated');
		if (pg.agentLens === 'device') return run.deviceId ? deviceLabelFor(run.deviceId) : tOr('agents.no_device', 'device not recorded');
		return '';
	}
	// A search reaches past the day: what has left the grid is still findable (think pass).
	DaimondAgentGrid.rows(runs, wait, { now: Date.now(), keepOld: !!pg.agentQuery }).forEach(function (row) {
		var r = document.createElement('div');
		r.className = 'agrow';
		r.setAttribute('role', 'group');
		var origin = agentOriginName(row.first);
		r.setAttribute('aria-label', origin);
		var o = agentThreadDiamond(row.orch.st, row.first, origin);
		if (row.items.some(function (it) { return agentMatches(it.run); })) o.classList.add('match');
		r.appendChild(o);
		row.items.forEach(function (it, i) {
			// A later orchestrating turn in this row: its own small diamond before its work.
			row.nested.forEach(function (n) {
				if (n.at !== i) return;
				r.appendChild(agentThreadDiamond('nested ' + n.st, n.first, origin));
			});
			var peer = !!peerIds[it.id];
			var b = document.createElement(peer ? 'span' : 'button');
			if (!peer) b.type = 'button';
			var pinned = !peer && pg.agentPins.indexOf(it.id) !== -1;
			b.className = 'agsq ' + it.st + (pinned ? ' pin' : '') + (agentMatches(it.run) ? ' match' : '');
			b.dataset.run = it.id;
			if (it.st === 'done') b.style.setProperty('--fade', String(it.fade));
			if (it.st === 'run') agentSquareFill(b, it.run);
			var word = it.st === 'wait' ? tOr('agents.status_waiting', 'waiting')
				: tOr('agents.status_' + it.run.status, it.run.status);
			var lensWord = lensDress(b, it.run);
			b.title = it.run.name + ' · ' + word + (lensWord ? ' · ' + lensWord : '');
			b.setAttribute('aria-label', it.run.name + ', ' + word + (lensWord ? ', ' + lensWord : ''));
			if (peer) b.setAttribute('role', 'img');
			else {
				b.setAttribute('aria-pressed', pinned ? 'true' : 'false');
				b.addEventListener('click', function () { setAgentPinned(it.id, pg.agentPins.indexOf(it.id) === -1); });
			}
			r.appendChild(b);
		});
		agentsGrid.appendChild(r);
	});
}

/// "Filter by tag" beside the search: the Diamond rail's own disclosure and its
/// vocabulary, so one tag filters both (think pass §6). A chip here sets the same
/// one-tag filter a tag chip on a tile sets.
export function renderAgentTagPool() {
	if (!agentTagf) return;
	agentTagf.innerHTML = '';
	var pool = tagPool();
	if (!pool.length) { agentTagf.style.display = 'none'; return; }
	agentTagf.style.display = '';
	var b = document.createElement('button');
	b.type = 'button';
	b.className = 'tagf-toggle';
	b.setAttribute('aria-expanded', pg.agentTagPoolOpen ? 'true' : 'false');
	b.title = pg.agentTagPoolOpen ? t('tag.pool_hide_help') : t('tag.pool_show_help');
	var chev = document.createElement('span');
	chev.className = 'tagf-chev';
	chev.setAttribute('aria-hidden', 'true');
	var lab = document.createElement('span');
	lab.className = 'tagf-label';
	lab.textContent = t('tag.pool_toggle', { n: pool.length });
	b.appendChild(chev); b.appendChild(lab);
	b.addEventListener('click', function () {
		pg.agentTagPoolOpen = !pg.agentTagPoolOpen;
		renderAgentTagPool();
		var nb = agentTagf.querySelector('.tagf-toggle');
		if (nb) nb.focus();
	});
	agentTagf.appendChild(b);
	if (!pg.agentTagPoolOpen) return;
	var row = document.createElement('div');
	row.className = 'tagf-pool';
	row.setAttribute('role', 'group');
	row.setAttribute('aria-label', t('tag.all'));
	pool.forEach(function (tag) {
		var c = tagChip(tag, pg.agentTagFilter === tag ? 'tag-active' : '', setAgentTagFilter);
		c.title = t('tag.only_agents', { tag: tag });
		c.setAttribute('aria-pressed', pg.agentTagFilter === tag ? 'true' : 'false');
		row.appendChild(c);
	});
	agentTagf.appendChild(row);
}

/// What to call the chat the panel is filtered to.
///
/// Asked of the runs rather than of the chat store, because `agentChatLabel`
/// already answers it for every state a chat can be in -- named, unnamed, or
/// gone to the trash with only the run's snapshot left.
function agentChatFilterLabel() {
	for (var i = 0; i < Workers.runs.length; i++) {
		if (Workers.runs[i].chatId === pg.agentChatFilter) return agentChatLabel(Workers.runs[i]);
	}
	return tOr('agents.from_chat', 'a chat');
}

/// The active agents filter, as one removable chip beside the search box,
/// so the list never quietly hides a run without saying why.
// ── Reading an agent, as a file rather than as a dialog ──────────
//
// Read used to open `noticeDialog(run.name, run.text)`: a modal over the app,
// holding a copy of the text that existed nowhere else, gone the moment it was
// dismissed. Three things were wrong with that and the tester named all three
// -- it should be a document on the stage, it should say WHERE it is, and it
// should keep up with an agent that is still working.
//
// So the transcript is written to the workspace and shown in the Doc panel.
// `system/agents/` beside `system/guide` and `system/usage`, which is where
// this app already keeps what it writes for itself to be read.
var AGENT_DIR = 'system/agents';

/// Where this run's transcript lives. Its id, so a re-read finds the same file
/// rather than making a second one, and so two agents of the same name do not
/// write over each other.
function agentDocPath(run) { return AGENT_DIR + '/' + run.id + '.md'; }

/// The transcript as a document: what was asked, what ran, and what was said.
///
/// Markdown, so it is readable as characters in the panel and readable as a
/// document anywhere else the user takes it. Everything in it is already on
/// the tile; the file is where it stops being a tile and becomes a record.
function agentDocText(run) {
	var out = ['# ' + (run.name || run.id), ''];
	var facts = [];
	facts.push('- Status: ' + run.status);
	if (run.model)       facts.push('- Model: ' + run.model
		+ (run.provider ? ' (' + run.provider + ')' : ''));
	if (run.diamondName) facts.push('- diamond: ' + run.diamondName);
	if (run.chatName)    facts.push('- Chat: ' + run.chatName);
	// Said in the file as well as on the tile: a transcript that does not
	// record that its worker read a stranger's words is a transcript somebody
	// could quote as if it had not.
	if (run.tainted)     facts.push('- This worker read words it did not get from you.');
	out = out.concat(facts, ['']);
	if (run.task) out = out.concat(['## Task', '', run.task, '']);
	if (run.tools && run.tools.length) {
		out.push('## Tools');
		out.push('');
		run.tools.forEach(function (x) { out.push('- ' + x.status + '  ' + x.name); });
		out.push('');
	}
	out.push('## Output');
	out.push('');
	// A running agent has said nothing yet, and an empty section reads as a
	// file that failed rather than as work that has not happened.
	out.push(run.text.trim() || '(nothing yet)');
	out.push('');
	return out.join('\n');
}

/// Write the transcript out and answer its path.
async function writeAgentDoc(run) {
	var path = agentDocPath(run);
	await Files.writeBytes(path, new TextEncoder().encode(agentDocText(run)));
	return path;
}

/// Which run the Doc panel is following, so only one loop is ever alive.
var agentDocFollow = null;
var agentDocTimer  = null;

/// Keep the file current while the agent works.
///
/// A poll and not a hook on the token stream, deliberately: a write per token
/// is a write per token, and the panel redraws on each one. Every 700ms the
/// file is rewritten IF the text has moved, and `Files.reshow` -- which the
/// `daimond-file-written` listener calls -- puts the new characters on screen.
/// That is the same relation `js/typstwatch.js` has to a `.typ`: one writer,
/// one notice, and the view follows.
///
/// It stops when the run stops, when the reader opens something else, or when
/// another run is read. Nothing is written for an agent nobody is reading.
function followAgentDoc(run) {
	if (agentDocTimer) { clearInterval(agentDocTimer); agentDocTimer = null; }
	agentDocFollow = run.id;
	var last = run.text;
	var path = agentDocPath(run);
	agentDocTimer = setInterval(async function () {
		var live = Workers.runs.find(function (r) { return r.id === run.id; }) || run;
		var reading = false;
		try { reading = Files.showing() === path; }
		catch (e) { reading = true; }   // no panel state: keep writing rather than stop
		var done = live.status !== 'running' && live.status !== 'queued'
			&& live.status !== 'paused';
		if (live.text !== last) {
			last = live.text;
			try { await writeAgentDoc(live); } catch (e) { /* no store; the next tick tries */ }
		}
		// The last write happens BEFORE the loop is dropped, so a finished
		// agent's file holds its whole output and not its last-but-one tick.
		if (done || !reading || agentDocFollow !== run.id) {
			if (done && live.text !== last) {
				try { await writeAgentDoc(live); } catch (e) { /* as above */ }
			}
			clearInterval(agentDocTimer);
			agentDocTimer = null;
			if (agentDocFollow === run.id) agentDocFollow = null;
		}
	}, 700);
}

/// The Read button: the transcript, on the stage, at a path, kept current.
export function readBtn(run) {
	var b = document.createElement('button');
	b.className = 'abtn';
	b.textContent = t('agents.read');
	b.title = tOr('agents.read_help',
		'Open this agent\u2019s transcript as a file in the Doc panel');
	b.addEventListener('click', async function () {
		var path;
		try { path = await writeAgentDoc(run); }
		catch (e) {
			// No workspace to write into. The dialog is what this used to be and
			// is still better than nothing, so it is the fallback and says why.
			noticeDialog(run.name, run.text.trim()
				|| tOr('agents.read_nothing', 'This agent has not said anything yet.'),
				{ pre: true });
			return;
		}
		try { await DaimondDoc.show(path); }
		catch (e) { await Files.open(path); }
		followAgentDoc(run);
	});
	return b;
}

/// A small pause / resume / stop button for an agent tile, echoing the
/// header controls: a glyph and a label, wired to the given action.
export function actBtn(kind, label, title, fn) {
	var b = document.createElement('button');
	b.className = 'abtn a-' + kind;
	var glyph = kind === 'pause' ? '⏸' : kind === 'play' ? '▶' : '✕';
	b.textContent = glyph + ' ' + label;
	b.title = title;
	b.addEventListener('click', fn);
	return b;
}

/// Show a plain-language tally of what the agents are doing, so a fan-out's
/// cost is legible at a glance: how many are running, paused and queued.
export function updateAgentStat(nRun, nPause, nQueue) {
	var el = document.getElementById('agents-stat');
	if (!el) return;
	// Through the catalogue, like everything else on this panel. These three
	// and the tile's own buttons were the last hardcoded English in a shipped
	// panel, and `dev/i18ncheck.mjs` could not see them: it compares key SETS
	// between locales, so a string that was never given a key is invisible to
	// it by construction.
	var parts = [];
	if (nRun)   parts.push(t('agents.tally_running', { n: nRun }));
	if (nPause) parts.push(t('agents.tally_paused',  { n: nPause }));
	if (nQueue) parts.push(t('agents.tally_queued',  { n: nQueue }));
	el.textContent = parts.join(' · ');
	el.style.display = parts.length ? '' : 'none';
}

/// Enable each header control only when it has something to act on, and hide
/// the group when there are no live or paused agents at all.
export function updateAgentControls(nRun, nPause, nQueue) {
	var grp = document.getElementById('agents-ctl');
	if (!grp) return;
	var active = nRun + nQueue;
	setAgc('agents-pause', active > 0);
	setAgc('agents-play',  nPause > 0);
	setAgc('agents-stop',  active + nPause > 0);
	grp.classList.toggle('holding', workersHeld() && nPause > 0);
	grp.style.display = (active + nPause) > 0 ? '' : 'none';
}
function setAgc(id, on) {
	var b = document.getElementById(id);
	if (b) b.disabled = !on;
}

export function renderAgentFilter() {
	if (!agentFilter) return;
	agentFilter.innerHTML = '';
	if (!pg.agentDiamondFilter && !pg.agentChatFilter && !pg.agentTagFilter) {
		agentFilter.style.display = 'none';
		return;
	}
	agentFilter.style.display = '';
	var chip;
	if (pg.agentDiamondFilter) {
		var f = null, id = pg.agentDiamondFilter;
		for (var i = 0; i < pg.diamonds.length; i++) if (pg.diamonds[i].id === id) { f = pg.diamonds[i]; break; }
		var label = f ? f.name : t('agents.a_diamond');
		chip = document.createElement('button');
		chip.className = 'tag-chip tag-active diamond-chip';
		chip.style.setProperty('--tag-h', tagHue(label));
		chip.textContent = '↳ ' + label;
		chip.title = t('agents.clear_diamond_filter');
		chip.addEventListener('click', function () { setAgentDiamondFilter(id); });
	} else if (pg.agentChatFilter) {
		// Hued off the chat's ID, exactly as the tile's chip is, so the standing
		// filter and the chip that set it are visibly the same thing.
		var cid = pg.agentChatFilter;
		chip = document.createElement('button');
		chip.className = 'tag-chip tag-active diamond-chip';
		chip.style.setProperty('--tag-h', tagHue(cid));
		chip.textContent = '↳ ' + agentChatFilterLabel();
		chip.title = t('agents.clear_chat_filter');
		chip.addEventListener('click', function () { setAgentChatFilter(cid); });
	} else {
		var tag = pg.agentTagFilter;
		chip = tagChip(tag, 'tag-active', function () { setAgentTagFilter(tag); });
		chip.title = t('tag.clear_filter', { tag: tag });
	}
	var x = document.createElement('span'); x.className = 'tag-x'; x.textContent = '×';
	x.setAttribute('aria-hidden', 'true');
	chip.setAttribute('aria-label', chip.title);
	chip.appendChild(x);
	agentFilter.appendChild(chip);
}

/// Every tag the pool has to offer: the ones in use across the store, plus
/// any the filter is holding.
///
/// The second half is what keeps a REFUSED tag reachable. Refusing one takes
/// every Diamond carrying it off the rail, so a pool drawn from the rail
/// would lose the chip along with them and leave the refusal on with nothing
/// to click. Read from the store instead, and the chip stays where it was.
///
/// Alphabetical, not by how often a tag is used. This row is standing
/// furniture in a fixed place, and a frequency order reshuffles it exactly
/// when it is being looked at -- file one Diamond and the chip you reached
/// for last time has moved. The tag editor's pool sorts the same way, so one
/// tag sits in one place in both.
function tagPool() {
	var seen = {};
	pg.diamonds.forEach(function (f) { tagsOf(f).forEach(function (x) { seen[x] = 1; }); });
	pg.tagInc.forEach(function (x) { seen[x] = 1; });
	pg.tagExc.forEach(function (x) { seen[x] = 1; });
	return Object.keys(seen).sort(function (a, b) { return a.localeCompare(b); });
}

/// One chip in the standing pool: the tag, and the state the rail holds it
/// in, drawn by the theme.
function poolChip(tag) {
	var st  = tagState(tag);
	var cls = 'tag-pool' + (st === 'inc' ? ' tag-inc' : st === 'exc' ? ' tag-no' : '');
	var chip = tagChip(tag, cls, cycleTagFilter);
	// The title says what the NEXT click does rather than what the chip is: a
	// chip already filtering looks like it has nothing left to give.
	chip.title = st === 'inc' ? t('tag.exclude_next', { tag: tag })
		: st === 'exc' ? t('tag.clear_exclude', { tag: tag })
		: t('tag.only_diamonds', { tag: tag });
	// Both marks are drawn in CSS (see `.tag-inc` and `.tag-no`) rather than
	// set as text: a chip's textContent is the tag, and the rail, the filter
	// and the search all read it. Someone who cannot see the mark is told
	// which state it is in, in words.
	if (st === 'inc') chip.setAttribute('aria-label', t('tag.exclude_next', { tag: tag }));
	if (st === 'exc') chip.setAttribute('aria-label', t('tag.not_tagged', { tag: tag }));
	return chip;
}

/// How two or more included tags combine, as two words with one of them on.
/// Both are shown rather than one label that toggles: a lone word cannot say
/// whether it is the state or the action, and the alternative stays visible.
function tagModeControl() {
	var grp = document.createElement('span');
	grp.className = 'tag-mode';
	grp.setAttribute('role', 'group');
	grp.setAttribute('aria-label', t('tag.mode_aria'));
	[['all', 'tag.mode_all', 'tag.mode_all_help'],
	 ['any', 'tag.mode_any', 'tag.mode_any_help']].forEach(function (m) {
		var b = document.createElement('button');
		b.className = 'tag-mode-btn' + (pg.tagMode === m[0] ? ' on' : '');
		b.dataset.mode = m[0];
		b.textContent = t(m[1]);
		b.title = t(m[2]);
		b.setAttribute('aria-pressed', pg.tagMode === m[0] ? 'true' : 'false');
		b.addEventListener('click', function (e) { e.stopPropagation(); setTagMode(m[0]); });
		grp.appendChild(b);
	});
	return grp;
}

/// Put the whole filter down at once.
function tagClearAll() {
	var b = document.createElement('button');
	b.className = 'tag-clear-all';
	b.textContent = t('tag.clear_all');
	b.title = t('tag.clear_all_help');
	b.addEventListener('click', function () {
		pg.tagInc = [];
		pg.tagExc = [];
		renderDiamondList();
	});
	return b;
}

function tagfRow(cls) {
	var d = document.createElement('div');
	d.className = 'tagf-row ' + cls;
	return d;
}

/// The one row the pool sits behind: what the feature is called, how many
/// tags are in it, and which way the next click goes.
///
/// The whole row is the target rather than the words. A rail is 250px of
/// mostly empty space to the right of a short label, and a hit area that
/// stops at the last letter is a control that gets missed.
///
/// The chevron is two borders on an empty box (see `.tagf-chev`), not a
/// character. An arrow typed into the label would be one absent glyph away
/// from saying nothing at all, and it would ride in the row's textContent,
/// where the count is read.
function tagPoolToggle(n) {
	var b = document.createElement('button');
	b.className = 'tagf-toggle';
	b.setAttribute('aria-expanded', pg.tagPoolOpen ? 'true' : 'false');
	b.title = pg.tagPoolOpen ? t('tag.pool_hide_help') : t('tag.pool_show_help');
	var chev = document.createElement('span');
	chev.className = 'tagf-chev';
	chev.setAttribute('aria-hidden', 'true');
	var lab = document.createElement('span');
	lab.className = 'tagf-label';
	lab.textContent = t('tag.pool_toggle', { n: n });
	b.appendChild(chev);
	b.appendChild(lab);
	b.addEventListener('click', function () { setTagPoolOpen(!pg.tagPoolOpen); });
	return b;
}

/// Open or close the pool, and keep the choice. Only the filter is repainted:
/// which Diamonds show has not changed, and repainting the rail under a
/// disclosure would flicker the list for nothing.
function setTagPoolOpen(open) {
	pg.tagPoolOpen = !!open;
	try { localStorage.setItem(TAG_POOL_KEY, JSON.stringify(pg.tagPoolOpen)); } catch (e) { /* best effort */ }
	renderTagFilter();
	// That paint replaced the row the click landed on, so focus would be left
	// on nothing and a keyboard could not close what it had just opened.
	var b = diamondFilter && diamondFilter.querySelector('.tagf-toggle');
	if (b) b.focus();
}

/// The tag filter, under the rail's head: one row naming it, the pool of every
/// tag in use behind that, and each chip cycling off -> wanted -> refused ->
/// off where it sits. It is now the only way the rail narrows, the search box
/// that stood above it having gone.
///
/// A POOL rather than a summary of what is on. A summary is only drawn once
/// something has been clicked, so the only way IN was a chip on a Diamond
/// box -- and a reader who went looking at the top of the rail for the filter
/// found nothing there at all. The pool says what the vocabulary is before
/// anything is touched, each chip carries its own state in place, and a
/// refused tag stays put even though its Diamonds have left the rail. That
/// makes the separate wanted and refused rows redundant -- they said in a
/// second place what a chip now says where it is -- so what is left below the
/// pool is only what is NOT a tag: how the wanted ones combine, and the one
/// click that puts the whole thing down.
///
/// What the pool could not be is PERMANENT. Thirty tags is three and a half
/// rows of chips paid for out of the rail's two lists on every screen, whether
/// anything is being filtered or not, so it collapses -- and what stands in
/// its place is a row that names it and counts it, because the fault it was
/// built to fix was a feature being read as absent.
///
/// Collapsed, a filter that is ON still speaks: the chips holding it come out
/// and stand on their own. A rail hiding Diamonds for a reason it will not
/// give is the same fault one size worse, and the alternative -- forcing the
/// pool open whenever anything filters -- hands the reader's own choice back
/// to them on the click that needed it least.
function renderTagFilter() {
	if (!diamondFilter) return;
	// A pool taller than its cap scrolls, and a repaint that lost the scroll
	// would throw the reader back to the top on every click.
	var was  = diamondFilter.querySelector('.tagf-pool');
	var top  = was ? was.scrollTop : 0;
	diamondFilter.innerHTML = '';
	var pool = tagPool();
	if (!pool.length) {
		diamondFilter.style.display = 'none';
		fitTagFilter();
		return;
	}
	diamondFilter.style.display = '';
	diamondFilter.appendChild(tagPoolToggle(pool.length));
	if (pg.tagPoolOpen) {
		var row = document.createElement('div');
		row.className = 'tagf-pool';
		row.setAttribute('role', 'group');
		row.setAttribute('aria-label', t('tag.all'));
		pool.forEach(function (tag) { row.appendChild(poolChip(tag)); });
		diamondFilter.appendChild(row);
		row.scrollTop = top;
	} else if (tagFiltering()) {
		// The same chips, from the same call, in the same order -- only fewer
		// of them. Nothing here is a second surface to keep in step with the
		// pool: a chip in this row IS a pool chip, standing somewhere else.
		var act = tagfRow('tagf-active');
		act.setAttribute('role', 'group');
		act.setAttribute('aria-label', t('tag.active_aria'));
		pool.forEach(function (tag) { if (tagState(tag)) act.appendChild(poolChip(tag)); });
		diamondFilter.appendChild(act);
	}
	if (tagFiltering()) {
		var ctl = tagfRow('tagf-ctl');
		// Offered only where it can change the answer: with one wanted tag
		// ALL and ANY name the same list, and a control that does nothing is
		// one more thing the reader has to rule out.
		if (pg.tagInc.length > 1) ctl.appendChild(tagModeControl());
		// Offered for a filter of any size. A pool chip has no closer -- its
		// text is the tag and nothing else -- so putting one tag down takes
		// two clicks round the cycle, and this is the one that does it in one.
		ctl.appendChild(tagClearAll());
		diamondFilter.appendChild(ctl);
	}
	fitTagFilter();
}

/// The filter is rail furniture, and the two lists below share what the
/// furniture leaves. It wraps when the chips outrun the rail's width, takes a
/// row when something is filtering, and takes or gives back the whole pool
/// when the disclosure is worked; every one of those changes the height, which
/// otherwise comes off the Chats list alone and quietly moves the divider. So
/// say what a window resize says -- but only when the height really moved,
/// since a filter is changed far more often than the furniture around it.
var tagFilterH = 0;         // the filter's height at its last paint
function fitTagFilter() {
	if (!diamondFilter) return;
	var h = diamondFilter.offsetHeight;
	if (h === tagFilterH) return;
	tagFilterH = h;
	railFurnitureChanged();
}

// 2026-09-15: the standing tag hint is gone, and with it `anyTagged`, which
// had no other caller. A line reading "No tags yet. Tag a diamond and filter
// chips appear here." was drawn under the Diamonds head on every account that
// had not tagged anything, behind a seventeen-word tooltip. It was written so
// that an empty pool would not read as a filing system somebody had removed --
// but the pool is not drawn when it is empty either, so there was nothing to
// misread, and what stood was an instruction to use a feature, paid for in
// rail height taken off the Chats list. Chips appear when tags exist.

/// The rail's two lists share what the furniture above them leaves, and a line
/// appearing or going takes that height off the Chats list alone. Say what a
/// window resize says, so the boundary is cut again.
///
/// Still needed once the divider is a height rather than a share, and for both
/// kinds of divider. An even split has to be re-cut, or the whole loss falls on
/// the Chats list; a chosen height is not re-cut, but the room it is clamped
/// against has changed, and a rail short enough for that to bite has to be told.
function railFurnitureChanged() {
	try { if (window.DaimondPanels) DaimondPanels.reflow(); } catch (e) { /* the layout is not up yet */ }
}

/// Is this one of the two Diamonds every account is seeded with?
///
/// Asked by id AND by name. The id is the honest answer -- `DEFAULT_IDS` fixes
/// one per name so two devices seed one object -- but an account seeded by an
/// engine too old to export `create_diamond_at` got a minted id, and those
/// accounts exist. The name is what identifies them there, and it is also the
/// key `seedDefaultDiamonds` de-duplicates on, so the two agree.
export function isBuiltInDiamond(f) {
	return !!builtInSlot(f);
}

/// Which built-in this Diamond is -- its `DEFAULT_IDS` key -- or '' for a person's own.
///
/// BY ITS FIXED ID OR ITS MARKER, NEVER BY ITS NAME (NAMES N1). The built-ins are called Neil
/// and Lucy, which are names a person gives a Diamond of their own, and matching by name put
/// such a Diamond in the shut Built-in group and, on the next boot, in the Trash. The marker
/// is `builtin` in the Diamond's own record, the fixed id it stands for; `markBuiltIns` sets it.
export function builtInSlot(f) {
	if (!f) return '';
	for (var n in DEFAULT_IDS) {
		if (DEFAULT_IDS[n] === f.id || DEFAULT_IDS[n] === f.builtin) return n;
	}
	return '';
}

// Whether the built-in group is open, per DEVICE. It is a fact about a screen
// -- a rail that is 300px tall wants it shut and a tall one may not -- and it
// must not travel in the parcel and reopen on the phone.
var BUILTIN_OPEN_KEY = 'daimond-builtin-open';

/// The built-ins, folded away at the foot of the Diamonds list.
///
/// A `<details>` rather than a div and a class: the disclosure triangle, the
/// keyboard route and the announced expanded/collapsed state all come with the
/// element, and every one of them would otherwise have to be built and then
/// kept right.
///
/// OPEN FOR A NARROWED VIEW, AND NOT SAVED (RAIL-SEARCH R1). A search or tag filter whose
/// matches are built-ins must show them, not file them behind a shut group; the person's own
/// open-or-shut choice is the one kept, so the toggle a browser fires for the forced open
/// writes nothing, and the next render without a search draws their choice again.
function builtInGroup(list) {
	var d = document.createElement('details');
	d.className = 'rail-builtin';
	var narrowed = railNarrowed();
	if (narrowed) d.open = true;
	else {
		try { d.open = localStorage.getItem(BUILTIN_OPEN_KEY) === '1'; }
		catch (e) { /* storage blocked: shut, which is the default anyway */ }
	}
	d.addEventListener('toggle', function () {
		if (narrowed) return;
		try { localStorage.setItem(BUILTIN_OPEN_KEY, d.open ? '1' : '0'); }
		catch (e) { /* quota: the choice holds for this session */ }
	});
	var sum = document.createElement('summary');
	sum.textContent = t('rail.builtin');
	d.appendChild(sum);
	list.forEach(function (f) { d.appendChild(diamondBox(f)); });
	return d;
}

/// Is the rail showing a narrowed view: a search typed, or a tag filter set?
function railNarrowed() {
	return !!pg.diamondQuery || pg.tagInc.length > 0 || pg.tagExc.length > 0;
}

export function renderDiamondList() {
	diamondList.innerHTML = '';
	renderTagFilter();
	if (pg.diamonds.length === 0) {
		var note = document.createElement('div');
		note.className = 'rail-note';
		note.textContent = t('rail.no_diamonds');
		diamondList.appendChild(note);
		repaintPause();
		return;
	}
	// Already most-recently-updated first: `list_diamonds` sorts on `updated`.
	var shown = pg.diamonds.filter(diamondMatches);
	if (shown.length === 0) {
		var none = document.createElement('div');
		none.className = 'rail-note';
		// A search that found nothing says so in two words, as the design has it;
		// a tag filter alone keeps its own longer line.
		none.textContent = pg.diamondQuery ? t('rail.search_none') : t('rail.no_match');
		diamondList.appendChild(none);
		repaintPause();
		return;
	}
	// THE TWO BUILT-INS GO TO THE FOOT, IN A GROUP THAT STARTS SHUT (RAIL-07).
	//
	// Every account is seeded "Neil" and "Lucy" -- they are
	// features, not decoration, and `seedDefaultDiamonds` says why nobody is
	// allowed to opt out of being offered them. But a person who has just
	// arrived meets a rail whose whole contents are two objects they did not
	// make, one of them wearing a play, a pause and a traffic light, before
	// they own anything at all.
	//
	// A disclosure answers both. They stay in the list, in the DOM, in the
	// pause tree, with their tiles and their controls exactly as they were --
	// `verify_defaults` still finds them in the store and `verify_optimiser`
	// still drives the tile -- but they are behind one word at the bottom
	// instead of in front of the first thing the eye reaches, and the
	// transport controls on the Optimiser's tile are not on the first screen.
	var mine = [], built = [];
	shown.forEach(function (f) { (isBuiltInDiamond(f) ? built : mine).push(f); });
	mine.forEach(function (f) { diamondList.appendChild(diamondBox(f)); });
	// An account whose only Diamonds are the built-ins has made none, and the
	// rail should say so rather than look like a list that failed to draw.
	// NOT WHILE A SEARCH OR FILTER NARROWS IT (R1): then the built-ins are what
	// matched, and "No diamonds yet." would be false to somebody with many.
	if (!mine.length && !railNarrowed()) {
		var own = document.createElement('div');
		own.className = 'rail-note';
		own.textContent = t('rail.no_diamonds');
		diamondList.appendChild(own);
	}
	if (built.length) diamondList.appendChild(builtInGroup(built));
	updateActiveDiamond();
	// A Diamond appearing or going moves the root and the section above it,
	// and neither of those lights is rebuilt here.
	repaintPause();
}

/// Move a Diamond to the trash. THE way a Diamond is removed by hand.
///
/// IT ASKS NOTHING and it DESTROYS NOTHING. The store keeps every byte of
/// `diamonds/<id>/` — the crystal, its versions, the log, the sidecars — and
/// so does the other device, because a Diamond is still collected into every
/// parcel while it is in the trash. What changes is a state that travels: it
/// leaves the rail, the graph, the fold picker and every daimon's reach, and
/// appears in the Trash panel with Restore beside it.
///
/// So the panel record, the pause flags, the tile's colours and the chosen
/// view all STAY. They are what makes a restore return the Diamond you
/// deleted rather than a Diamond with its name. Forgetting them is part of
/// destroying it, and lives in `destroyDiamond`.
///
/// The daimon's conversation rides with its Diamond rather than being trashed
/// beside it: a chat with a `diamondId` has no tile of its own, so a second
/// entry in the panel would be one act of the user's shown as two things to
/// restore. It becomes unreachable exactly when its Diamond does, and is
/// destroyed with it.
///
/// Resolves true when the Diamond went.
async function deleteDiamond(f) {
	try { DaimondTrash.put(f.id, 'diamond'); }
	catch (e) {
		// No trash module in this build. Falling back to a silent permanent
		// deletion would be the exact failure this feature exists about, so it
		// refuses and says why instead.
		noticeDialog(t('rail.delete_failed'), friendlyError(e));
		return false;
	}
	if (pg.currentDiamond && pg.currentDiamond.id === f.id) {
		pg.currentDiamond = null;
		signalDiamondChanged();
		sessionNameEl.textContent = t('chat.no_chat');
		showCentre('chat');
		renderEmptyState();
	}
	// A daimon mid-turn in a Diamond that has just left the rail must stop:
	// the reply would land on a conversation nobody can reach and be billed
	// for it. Same rule `detachChat` keeps for an ordinary chat.
	var dchat = pg.chats.find(function (c) { return c.diamondId === f.id; });
	if (dchat) { detachChat(dchat); persistChats(); }
	bumpDiamonds();
	await loadDiamonds();
	// The same window a chat gets, for the same reason: the trash is the
	// commit, and the five seconds are for the press somebody regrets at
	// once rather than for the panel they would otherwise have to hunt.
	undoAble(t('undo.deleted', { name: f.name }), function () { trashRestore(f.id); });
	return true;
}

/// Destroy a Diamond for good: the store, the tombstone, and everything that
/// was kept against a restore. There is no way back and nothing calls it
/// without having asked. Resolves true when the Diamond went.
export async function destroyDiamond(id) {
	var f = pg.diamonds.find(function (x) { return x.id === id; }) || { id: id };
	// THE TOMBSTONE GOES DOWN FIRST, AND DURABLY (S-SYNC #6). It records the
	// account's decision -- true whether or not this device holds the bytes --
	// and it travels. If it cannot be landed in IndexedDB the deletion is
	// REFUSED and nothing else happens, rather than deleting the store copy
	// while the deletion never reaches the other devices, which held the Diamond
	// back on them silently for ever. The old code swallowed the quota throw.
	if (!id) return false;
	var _dat = Date.now(), _dobj = {}; _dobj[id] = _dat;
	if (!(await ChatStore.putTombs(DIAMOND_TOMBS_KEY, _dobj))) {
		storageAlarm(tOr('store.delete_unrecorded',
			'a deletion could not be recorded — this browser’s storage is full'));
		return false;
	}
	tombMark(DIAMOND_TOMBS_KEY, [id], _dat);   // durable now: safe to overlay and delete
	// Its alerts are taken down, synced, so no badge counts what no daimon is left to clear.
	try {
		if (window.DaimondAlerts) DaimondAlerts.live().forEach(function (a) {
			if (a.diamond === id) DaimondAlerts.dismiss(a.id);
		});
	} catch (e) { /* the tombstone hides them anyway (Pending.fresh) */ }
	// A destroyed Diamond's panel record has nothing left to restore (UNBLOCK-14).
	try { if (window.DaimondPanelRec) DaimondPanelRec.drop(id); } catch (e) { /* no store */ }
	// And its pause flags, for the same reason: a leaf id nobody can reach
	// keeps the Diamonds section — and the root above it — amber for ever,
	// and travels in every sync parcel for the life of the account.
	try { DaimondPause.forget(DaimondPause.id('root', 'diamonds', id)); }
	catch (e) { /* module not up */ }
	// And what was pressed on it here. Trashing keeps them, since a restore brings
	// the scope back; destroying is for good.
	DaimondMarksHere.dropAll(id);
	// And its folders' answered marks, which are otherwise never drained (r569 A3).
	pruneMailMarks(id, true);
	forgetTilePrefs(id);
	setDiamondFolder(id, '');
	forgetDiamondView(id);
	// The daimon's conversation goes with its daimon. Left behind it would be a
	// chat record with no tile, no Diamond and no way to reach it, sitting in
	// IndexedDB and travelling in every sync parcel for the life of the account —
	// and `daimonChat` would hand it back if the id were ever reused.
	var dchat = storedChats().find(function (c) { return c.diamondId === id; });
	if (dchat) await destroyChat(dchat.id);
	try {
		await diamondApp().delete_diamond(id);
	} catch (e2) {
		// Not a dialog. Nothing is lost and nothing is stuck: the tombstone
		// above is already down, so this device deletes its own copy on the
		// next merge exactly as the others delete theirs.
		try { console.warn('[trash] the store would not delete ' + id + '; the tombstone stands', e2); }
		catch (e3) { /* no console */ }
	}
	try { DaimondTrash.forget(id); } catch (e) { /* module not up */ }
	if (pg.currentDiamond && pg.currentDiamond.id === id) {
		pg.currentDiamond = null;
		signalDiamondChanged();
		sessionNameEl.textContent = t('chat.no_chat');
		showCentre('chat');
		renderEmptyState();
	}
	bumpDiamonds();
	await loadDiamonds();
	return true;
}

/// A DIAMOND'S CHIPS ARE ONE ROW OF WHOLE CHIPS, under its name, on every width (CHIPLINE,
/// D-20261024-04, his overflow pick 24 Oct). The chips that do not fit whole fold, from the
/// end, into one "+N" button, and "+N" opens the tile's every tag as filter chips
/// (`openTagMore`); if even "+N" does not fit, the strip draws no chip past it. No chip is
/// cut and the row never scrolls: a sideways strip hid its last tags, and a phone strip on
/// the name's line cut its last chip under the gear (UNBLOCK-33 F8).
function foldTags(strip) {
	var chips = Array.prototype.filter.call(strip.children, function (c) {
		return c.classList.contains('tag-chip') && !c.classList.contains('tag-more');
	});
	var more = strip.querySelector(':scope > .tag-more');
	chips.forEach(function (c) { c.classList.remove('tag-fold'); });
	if (more) more.hidden = true;
	if (!strip.isConnected || !strip.clientWidth) return;
	var cs = getComputedStyle(strip);
	var edge = strip.getBoundingClientRect().right - (parseFloat(cs.paddingRight) || 0) + 0.5;
	var fits = function (el) { return el.getBoundingClientRect().right <= edge; };
	if (!chips.length || fits(chips[chips.length - 1])) return;
	if (!more) {
		more = document.createElement('button');
		more.type = 'button';
		more.className = 'tag-chip tag-sm tag-more';
		more.setAttribute('aria-haspopup', 'true');
		more.setAttribute('aria-expanded', 'false');
		more.addEventListener('click', function (e) {
			e.stopPropagation();                   // the tile's own click opens the Diamond
			openTagMore(more, chips.map(function (c) { return c.textContent; }));
		});
		// Enter and Space on it are its own, not the tile's (the tile's keydown answers only to itself).
		strip.appendChild(more);
	}
	more.hidden = false;
	var hid = [];
	for (var k = chips.length - 1; k >= 0; k--) {
		chips[k].classList.add('tag-fold');
		hid.unshift(chips[k].textContent);
		more.textContent = '+' + hid.length;
		more.title = hid.join(', ');
		more.setAttribute('aria-label', t('tag.more_all', { tags: hid.join(', ') }));
		if (fits(more)) return;
	}
	more.hidden = true;
}
// page-split: install 110
function foldTagsWatch(strip) {
	if (!tagFoldRo) return;
	tagFoldRo.observe(strip);
	Array.prototype.forEach.call(strip.children, function (c) { tagFoldRo.observe(c); });
}

// ── "+N": a tile's every tag, each still a filter chip ──────
// A popover off the "+N" button, the shape `openChatsMenu` draws: a layer, so Escape and
// Back close it and the keyboard returns to "+N"; a press outside closes it too. A chip
// here does what the tile's own chip does (`cycleTagFilter`), and the rail it redraws
// takes this popover's anchor with it, so the press closes it first.
var _tagMore = null;
function closeTagMore() {
	if (!_tagMore) return;
	var pop = _tagMore;
	_tagMore = null;
	pop.el.remove();
	document.removeEventListener('click', onTagMoreOutside, true);
	DaimondLayers.done('tagmore');
	pop.anchor.setAttribute('aria-expanded', 'false');
}
function onTagMoreOutside(e) {
	var anchor = _tagMore && _tagMore.anchor;
	if (_tagMore && !_tagMore.el.contains(e.target) && !(anchor && anchor.contains && anchor.contains(e.target))) closeTagMore();
}
function openTagMore(anchor, tags) {
	if (_tagMore) { var was = _tagMore.anchor; closeTagMore(); if (was === anchor) return; }	// a second press toggles it shut
	var pop = document.createElement('div');
	pop.className = 'railhead-menu tag-more-pop';
	pop.setAttribute('role', 'group');
	pop.setAttribute('aria-label', t('tag.all_tags'));
	tags.forEach(function (tag) {
		var on   = tagState(tag) === 'inc';
		var chip = tagChip(tag, 'tag-sm' + (on ? ' tag-inc' : ''), function (tg) { closeTagMore(); cycleTagFilter(tg); });
		chip.title = on ? t('tag.exclude_next', { tag: tag }) : t('tag.only_diamonds', { tag: tag });
		pop.appendChild(chip);
	});
	_tagMore = { el: pop, anchor: anchor };
	DaimondLayers.hang(pop, 'tagmore', closeTagMore, anchor);
	var r = anchor.getBoundingClientRect();
	pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - pop.offsetWidth - 8)) + 'px';
	var top = r.bottom + 4;
	if (top + pop.offsetHeight > window.innerHeight - 8) top = Math.max(8, r.top - 4 - pop.offsetHeight);
	pop.style.top = top + 'px';
	anchor.setAttribute('aria-expanded', 'true');
	if (pop.firstChild) pop.firstChild.focus({ preventScroll: true });
	setTimeout(function () { document.addEventListener('click', onTagMoreOutside, true); }, 0);
}

function diamondBox(f) {
	var box = document.createElement('div');
	// As on a chat tile: `paintRailRow` is the one place that decides which of
	// the rail's two selections wears the accent, and `renderDiamondList` calls
	// it through `updateActiveDiamond` once the list is built.
	box.className = 'session-box diamond-box';
	box.dataset.id = f.id;
	// How much of itself this tile draws — the global view sets it.
	box.dataset.detail = tileDetail();
	// The row IS the control, so it has to be one to the keyboard and to a
	// screen reader as well as to the pointer. It was a div with a click
	// handler whose only focusable child was the x that deletes it, so
	// tabbing the rail reached "delete this Diamond" twice and "open this
	// Diamond" never: the destructive act had a keyboard route and the
	// central one did not.
	box.setAttribute('role', 'button');
	box.setAttribute('tabindex', '0');
	box.setAttribute('aria-label', f.name || t('rail.unnamed_diamond'));
	box.addEventListener('keydown', function (e) {
		if (e.key !== 'Enter' && e.key !== ' ') return;
		// Not when the press belongs to something inside the row -- the cog,
		// the light, or a tag chip -- which answer for themselves.
		if (e.target !== box) return;
		e.preventDefault();
		box.click();
	});
	var header = document.createElement('div');
	header.className = 'session-box-header';
	var name = document.createElement('span');
	name.className = 'session-box-name';
	paintDiamondName(name, f.name);            // text nodes only (H5)
	name.title = t('rail.dblclick_rename');
	name.addEventListener('dblclick', async function (e) {
		e.stopPropagation();
		var nn = await promptDialog(t('rail.rename_diamond'), { value: f.name, okLabel: t('rail.rename') });
		if (nn === null) return; nn = nn.trim();
		if (!nn || nn === f.name) return;
		renameDiamondTo(f.id, f.name, nn, function (n2) { f.name = n2; })
			.catch(function (e2) { noticeDialog(t('rail.rename_failed'), friendlyError(e2)); });
	});
	// ITS ICON, before the name (D-20261015-13): a default guessed from the name and tags,
	// changed by pressing it. js/avatar.js.
	if (window.DaimondAvatar) header.appendChild(DaimondAvatar.button({ kind: 'diamond', id: f.id, name: f.name, tags: tagsOf(f) }));
	header.appendChild(name);
	// The Diamond's own traffic light, bound to the branch that carries its
	// daimon and its triggered actions — so a Diamond with a trigger paused
	// and a daimon running reads amber here without anyone having set amber
	// anywhere.
	//
	// AFTER THE NAME, right-aligned against the cog rather than in front of
	// the label. The user's call, and it is the consistent one: a tile that
	// has a widget and one that has not then differ only in what sits beside
	// the cog, so a rail of mixed Diamonds keeps one left edge for its names.
	//
	// And ONLY where there is something to pause. A Diamond with no triggered
	// actions spends when the user prompts it and at no other time, so a
	// control for it would stand for a decision already made by typing.
	//
	// ASKED HERE, and it has to be. Dropping the Diamond from `pauseTree` does
	// NOT stop the widget by itself: `pauseGoverns` answers `true` for a node
	// it cannot find in the tree -- deliberately, because that is how a TA's
	// own leaf gets a control -- so a TA-less Diamond would otherwise draw a
	// green light that governed nothing and could not be turned off. Which is
	// the very fault `pauseWidget`'s own comment records from the Email panel.
	if (diamondAutomated(f.id)) {
		mountPause(header, DaimondPause.id('root', 'diamonds', f.id),
			f.name || t('rail.unnamed_diamond'));
	}
	header.appendChild(tileCog(f.name, function () {
		openTileDialog({
			id:   f.id,
			name: f.name,
			// The BRANCH, not the `self` leaf: a Diamond's control stands for
			// its daimon and its triggered actions together, so one with a
			// trigger held and a daimon running reads amber here without
			// anyone having set amber anywhere.
			//
			// ALWAYS, even where the tile draws no widget. This dialog is the
			// release valve: a Diamond held by the global control needs
			// somewhere to be let go from, and taking the light off the tile
			// is a statement about clutter, not about whether the object can
			// be paused.
			node: DaimondPause.id('root', 'diamonds', f.id),
			// A Diamond's models may be changed after it is made; a chat's may not.
			models:   'diamond',
			onDelete: function () { return deleteDiamond(f); },
		});
	}));
	// THE META ROW KEEPS THE MODEL CHIP AND NOTHING ELSE. The version number
	// was tile furniture nobody compared, and the time and the spend moved down
	// to the meter row where they sit beside the thing they measure. A pending
	// fold is a warning and warnings never leave the tile, so it stays here
	// rather than being tidied into the meter row where it would read as a
	// reading.
	var meta = document.createElement('div');
	meta.className = 'session-box-meta';
	// The daimon's conversation, found WITHOUT creating one -- `daimonChat` would
	// mint an empty session for a Diamond the user has never opened. Read here
	// rather than in the meter row below because two rows want it now: the queue
	// badge on this row, and the context bar on that one.
	var dc = pg.chats.find(function (c) { return c.diamondId === f.id; });
	// What this Diamond thinks with. Stored since Diamonds had models and drawn
	// nowhere, so two Diamonds deliberately put on different models looked identical
	// on the rail — and a fan-out is billed to this pair. Detail, so Simple hides it
	// with the other model controls; the cog's dialog is where it is changed.
	var dm = diamondModel(f.id);
	if (dm && dm.model) {
		var mchip = document.createElement('span');
		mchip.className = 'tile-model-chip diamond-model';
		mchip.textContent = shortModel(dm.model, dm.provider);
		mchip.title = t('tile.diamond_model_help', { model: dm.model });
		meta.appendChild(mchip);
	}
	// (No pending-fold badge any more: folds commit directly — owner decision
	// 2026-09-04 — so a Diamond is never left with a proposal waiting on it.)
	// What is waiting on this Diamond's daimon, in the same words and the same
	// style the chat tile uses -- a daimon's conversation is an ordinary chat
	// record, so it queues the way one does and there is no second thing to say
	// about it. ON THIS ROW rather than the meter row below, because the
	// stylesheet keeps a meta row alive in Simple exactly when it holds a
	// `.diamond-pending` and this badge is one, while `.diamond-meter` is hidden
	// in Simple outright. `app.css` states that Simple keeps the queue badge; the
	// meter row is the one place on this tile where that would have been false.
	//
	// `updateQueueBadges` maintains it after this, and it has to find the same
	// row -- see `queueBadgeSlot`, which both ends call so they cannot drift.
	var qb = queueBadge(dc);
	if (qb) meta.appendChild(qb);
	// A meta row holding nothing still costs its top margin, which is why the
	// meter row below is guarded the same way. It empties whenever a Diamond has
	// no model set, no fold pending and nothing queued -- the ordinary state of a
	// new one.
	box.appendChild(header);
	// WHO GAVE IT TO YOU, under the name, in THIS device's colours. Colours are
	// a device preference and the sender's are not carried, so a shared diamond
	// looks like the rail it is on; what is borrowed is the name. A LINE AND NOT
	// A BADGE: a badge is an official shape and only a verified key could earn
	// one, and the key's standing is said in People, where it can be acted on.
	// Below the header rather than inside it, which is a flex row holding the
	// name, the light and the cog.
	var from = _origins[f.id];
	if (from && from.handle) {
		var fl = document.createElement('div');
		fl.className = 'diamond-from';
		fl.textContent = t('rail.shared_by', { who: from.handle });
		box.appendChild(fl);
	}
	if (meta.firstChild) box.appendChild(meta);
	// The meter row, BELOW the tags and shaped like the one on an ordinary
	// chat tile: context bar with its percentage, then the relative time that
	// used to sit in the meta row, then the spend. No token count, as on a chat
	// tile (D-20261010-04): the percentage is the reading that matters.
	// The spend figure is the Diamond's OWN — the signals-index figure that was
	// already on the tile — and NOT the daimon conversation's cost, for the same
	// reason.
	//
	// The context bar is drawn only when the daimon has spent tokens AND its
	// model publishes a window. A missing bar means one of those two, and the
	// caller does not invent a placeholder.
	var meterRow = document.createElement('div');
	meterRow.className = 'diamond-meter';
	// THE GUARD USED TO ASK ABOUT TWO COUNTERS NOTHING ON THIS PATH WRITES, so the
	// bar this row was built to carry was never once drawn on a Diamond. A daimon's
	// turn goes through `doSteer`, which sets `rec.lastPrompt` from the engine and
	// bills the turn to the Diamond through `meterDiamondTurn`; `promptTokens` and
	// `completionTokens` are maintained only by `runTurn`, and `sendUserMessage`
	// diverts a daimon's conversation away from it. So the tile read
	// `22h ago  ~A$3.40` with a real reading available and unasked for.
	//
	// Nothing takes its place: `tileCtxBar` already refuses when the window is
	// unpublished or the daimon has never spoken, and asking IT is the whole of the
	// question. The bar is the chat tile's own, so the two cannot come to mean
	// slightly different things.
	var bar = dc ? tileCtxBar(dc, daimonWindow(dc)) : null;
	if (bar) meterRow.appendChild(bar);
	// U3 (D-20260929-03 varlen sweep): the spend figure comes BEFORE the
	// relative time now, not after, so the free-text time is the meter's
	// LAST reading in every tile. A figure ("~A$3.40") ellipsising mid-number
	// reads as a different amount; the relative time ("22h ago") is the one
	// reading in this row safe to give way, and V6's `:last-child` rule
	// (skin-daylight.css) only ever touches whichever one sits last.
	try {
		if (window.DaimondSignals) {
			var ix = DaimondSignals.snapshot();
			var mine = ix && ix.diamonds && ix.diamonds[f.id];
			if (mine && (mine.usd || 0) > 0) {
				meterRow.appendChild(DaimondI18n.priceTag(mine.usd, { cls: 'session-box-spend',
					note: t('tile.spend_help', { turns: mine.turns || 0 }) }));
			}
		}
} catch (e) { /* no index yet: the row says nothing about spend */ }
	if (f.updated) {
		var upd = document.createElement('span');
		upd.className = 'session-box-time';
		upd.textContent = relTime(f.updated);
		meterRow.appendChild(upd);
	}
	// A row with nothing in it still costs its margin-top, so it is not appended
	// at all rather than appended empty.

	// Tags in their own row, under the name (CHIPLINE, D-20261024-04: his pick over the
	// name's line of D-20261023-05 eye F1/F8). One row of whole chips at every width:
	// `foldTags` folds those that do not fit into one "+N", which opens them all.
	var tags = tagsOf(f);
	if (tags.length > 0) {
		var tagsRow = document.createElement('div');
		tagsRow.className = 'session-box-tags';
		tags.forEach(function (tag) {
			// A Diamond only reaches the rail if it passed the filter, so a chip
			// here is either off or included -- never excluded. The title says
			// what the next click does rather than what the chip is, because a
			// chip that already filters looks like it has nothing left to give.
			var on   = tagState(tag) === 'inc';
			var chip = tagChip(tag, 'tag-sm' + (on ? ' tag-inc' : ''), cycleTagFilter);
			chip.title = on ? t('tag.exclude_next', { tag: tag }) : t('tag.only_diamonds', { tag: tag });
			tagsRow.appendChild(chip);
		});
		box.appendChild(tagsRow);
		foldTagsWatch(tagsRow);
	}
	// THE METER ROW GOES LAST, BELOW THE TAGS, which is where it was asked to be.
	// It is built further up and appended here: the comment on its construction
	// said "BELOW the tags" while the append stood three lines ABOVE them, so the
	// tile drew the opposite of what the line beside it claimed. A row with
	// nothing in it still costs its margin, so an empty one is not appended.
	if (meterRow.firstChild) box.appendChild(meterRow);
	box.addEventListener('click', function () {
		selectDiamond(f);
		if (isMobile()) mshow('ai');
	});
	// Last, so every span this tile is made of is already in it.
	paintTileColour(box, f.id);
	return box;
}

export function updateActiveDiamond() {
	var focused = railFocus() === 'diamonds';
	diamondList.querySelectorAll('.diamond-box').forEach(function (box) {
		paintRailRow(box, pg.currentDiamond && box.dataset.id === pg.currentDiamond.id, focused);
	});
}

/// The AI panel's own two faces: the chat thread, and a Diamond's crystal.
///
/// A document and a message used to be shown HERE, in place of the chat —
/// so reading your mail meant leaving the conversation. They are stage
/// panels now, and open beside it.
/// `'chat'` — an ordinary chat. `'focus'` — a Diamond's crystal. `'daimon'` — a
/// Diamond's conversation, which uses the chat's own thread and composer.
///
/// The three are `CENTRE_FACES`, and this is the only thing that writes
/// `centreMode`. A fourth is refused rather than entered: every guard in the
/// file asks which face is up, so an unknown one would turn all of them off at
/// once and the Centre would quietly stop drawing anything.
/// Show how long since this Diamond was last edited, beside the label.
///
/// The crystal VERSION number that used to sit here carried no user value — it
/// is an internal counter, not something a reader acts on — so it is dropped
/// (owner review 2026-09-04). The "edited" time moves to the left of the header,
/// in `#chead-when`, beside the name and the face switch.
export function setDiamondWhen(f) {
	var w = document.getElementById('chead-when');
	if (w) w.textContent = (f && f.updated) ? relTime(f.updated) : '';
	// The right-hand meter no longer carries "crystal vN"; clear the stale text.
	if (aiMeter && /^crystal v/.test(aiMeter.textContent || '')) aiMeter.textContent = '';
}

/// The open Diamond's or chat's icon, 18px, before its title in the panel head. It takes the
/// mark's place where there is one to draw: the icon says which Diamond, the mark only that it
/// is one. Repainted whenever the title changes (see the observer in `wireAvatars`).
export function paintHeadAvatar() {
	var host = document.getElementById('chead-av');
	var mark = document.getElementById('chead-mark');
	if (!host) return;
	var A = window.DaimondAvatar, onD = !!pg.currentDiamond && (pg.centreMode === 'focus' || pg.centreMode === 'daimon');
	var html = '';
	if (A && onD) html = A.svg(A.iconFor('diamond', pg.currentDiamond.id, pg.currentDiamond.name, tagsOf(pg.currentDiamond)), 18);
	else if (A && pg.current && !pg.current.diamondId) html = A.svg(A.iconFor('chat', pg.current.id, chatIconName(pg.current), []), 18);
	if (host.innerHTML !== html) host.innerHTML = html;
	host.style.display = html ? '' : 'none';
	if (mark && html) mark.style.display = 'none';
}
export function showCentre(mode) {
	if (CENTRE_FACES.indexOf(mode) < 0) {
		try { console.warn('[centre] no such face: ' + mode); } catch (e) { /* no console */ }
		return;
	}
	pg.centreMode = mode;
	var crystalOn = (mode === 'focus');
	var onDiamond = crystalOn || mode === 'daimon';
	// A hidden frame is still a live frame: it holds a blob URL and a `message`
	// listener, and left alone it would answer the next Diamond's page from the last
	// one's data. Leaving the crystal face takes it down; coming back re-mounts.
	if (!crystalOn) clearCrystalBody();
	crystalView.style.display  = crystalOn ? 'flex' : 'none';
	chatOutputEl.style.display = crystalOn ? 'none' : '';
	// THE COMPOSER STAYS ON BOTH FACES OF A DIAMOND.
	//
	// It used to be hidden here, because the crystal carried its own "steer"
	// box underneath it. That box is gone -- a daimon is one persistent
	// conversation, so a second place to type into it was two ways to say the
	// same thing. But removing the box and keeping this line would have made
	// the crystal a DEAD END: the face you land on, by design, with no way to
	// say anything from it.
	//
	// What "redundant" meant was a second composer, not no composer. So the
	// one composer shows under whichever face is up, and what is typed goes
	// to the daimon either way -- `sendUserMessage` already routes a Diamond's
	// message through `doSteer`.
	chatInputBar.style.display = (crystalOn && !onDiamond) ? 'none' : '';
	// FULL SCREEN BELONGS TO THE CRYSTAL FACE AND TO NOTHING ELSE. The mode
	// covers the app in order to show one page; with that page gone it would be
	// a covered app with no subject, and the control that ends it would have
	// gone with the face it lives on. So the face switch, and every path that
	// reaches it -- another Diamond, a chat, the rail -- puts it down.
	if (!crystalOn && crystalFull) setCrystalFull(false);
	var fullBtn = document.getElementById('crystal-full-btn');
	if (fullBtn) {
		fullBtn.style.display = crystalOn ? '' : 'none';
		syncCrystalFullBtn();
	}
	// Which face is up, said in the panel's own shape: the crystal wears the
	// mark and squares its corners against the rounded chrome everywhere else.
	// A daimon's chat is a conversation, so it wears neither.
	var ai = document.getElementById('panel-ai');
	if (ai) ai.classList.toggle('crystal-face', crystalOn);
	// The mark reads "this is a Diamond", so it wears on BOTH of a Diamond's
	// faces — the crystal AND the chat — and on an ordinary chat it does not.
	// It used to appear on the crystal face alone, so switching a Diamond to its
	// chat face dropped the mark and the header looked like an ordinary chat's
	// (owner review 2026-09-04: "some show it, some don't, with no pattern").
	var mark = document.getElementById('chead-mark');
	if (mark) mark.style.display = onDiamond ? '' : 'none';
	// Its own icon now stands where the mark stood (D-20261015-13), on a chat as on a Diamond.
	paintHeadAvatar();
	// The "edited" time belongs to a Diamond; an ordinary chat clears it.
	if (!onDiamond) { var cw = document.getElementById('chead-when'); if (cw) cw.textContent = ''; }
	// Fold belongs to the face that shows the conversation.
	try { syncFoldBtn(); } catch (e) { /* not wired yet at first paint */ }
	// The face switch belongs to a Diamond and nothing else: a chat has one face,
	// and a switch offering it a second would be a control that does nothing.
	var sw = document.getElementById('diamond-view');
	if (sw) {
		sw.style.display = onDiamond ? '' : 'none';
		var cb = document.getElementById('dview-crystal');
		var hb = document.getElementById('dview-chat');
		if (cb) cb.setAttribute('aria-pressed', crystalOn ? 'true' : 'false');
		if (hb) hb.setAttribute('aria-pressed', crystalOn ? 'false' : 'true');
	}
	// The face decides which of the rail's two selections wears the accent, so
	// both lists are repainted here rather than only where a row is clicked --
	// the face also changes from the view switch, from a fold and from a link.
	try { updateActiveDiamond(); updateActiveSession(); }
	catch (e) { /* the lists are not built at first paint */ }
}

/// Show one mail message on the stage, beside the chat — so it can be read
/// and asked about at the same time.
///
/// The body is set as text, never as markup. A mail body is the least
/// trustworthy string in the application, and this is the only place one
/// meets the DOM.
/// Render one message the way a mail client does: a header block you can actually read the
/// sender out of, the body, and the files that came with it.
///
/// HTML mail is a stranger's markup. It is never inserted into this document — it is written
/// into a sandboxed iframe with no scripts, no access to our origin, and a content policy that
/// refuses every remote load. That last part is not only about safety: a remote image in a mail
/// is a tracking pixel, and fetching it tells the sender you opened their message. So pictures
/// stay off until the reader asks for them, exactly as every other mail client does.
export function showMessage(v) {
	var head = document.getElementById('msg-head');
	var body = document.getElementById('msg-body');
	if (!head || !body) return;

	var title = document.getElementById('msg-title');
	if (title) title.textContent = v.subject || t('panel.msg');

	// ── The header block ───────────────────────────────────
	head.innerHTML = '';
	var subj = document.createElement('div');
	subj.className = 'msg-subject';
	subj.textContent = v.subject || t('mail.no_subject');
	head.appendChild(subj);

	var who = document.createElement('div');
	who.className = 'msg-who';
	var from = v.from || { name: '', addr: '' };
	var nm = document.createElement('span');
	nm.className = 'msg-name';
	nm.textContent = from.name || from.addr || t('msg.unknown_sender');
	who.appendChild(nm);
	if (from.name && from.addr) {
		var ad = document.createElement('span');
		ad.className = 'msg-addr';
		ad.textContent = '<' + from.addr + '>';
		who.appendChild(ad);
	}
	if (v.date) {
		var dt = document.createElement('span');
		dt.className = 'msg-date';
		dt.textContent = window.DaimondTime.fmtLocal(v.date, 'whenFull') || v.date;	// a header we cannot read, verbatim
		who.appendChild(dt);
	}
	head.appendChild(who);

	[[t('compose.to'), v.to], [t('compose.cc'), v.cc], [t('msg.reply_to'), v.replyTo]].forEach(function (row) {
		if (!row[1]) return;
		var d = document.createElement('div');
		d.className = 'msg-line';
		d.innerHTML = '<span class="msg-lbl"></span><span class="msg-val"></span>';
		d.querySelector('.msg-lbl').textContent = row[0];
		d.querySelector('.msg-val').textContent = row[1];
		head.appendChild(d);
	});

	// The verbs sit on the message, where the reader is when they decide to answer it.
	if (v.reply) {
		var acts = document.createElement('div');
		acts.className = 'msg-acts';
		var verbs = [[t('msg.reply'), v.reply]];
		if (v.canReplyAll) verbs.push([t('msg.reply_all'), v.replyAll]);
		verbs.push([t('msg.forward'), v.forward]);
		verbs.forEach(function (verb) {
			var b = document.createElement('button');
			b.className = 'msg-act';
			b.textContent = verb[0];
			b.addEventListener('click', verb[1]);
			acts.appendChild(b);
		});
		head.appendChild(acts);
	}

	if (v.attachments && v.attachments.length) {
		var box = document.createElement('div');
		box.className = 'msg-atts';
		v.attachments.forEach(function (att) {
			var chip = document.createElement('button');
			chip.className = 'msg-att';
			chip.title = t('msg.save_help');
			chip.textContent = att.name + ' · ' + fmtBytes(att.size);
			chip.addEventListener('click', async function () {
				chip.disabled = true;
				try {
					var path = await v.save(att);
					chip.textContent = t('msg.saved_to', { path: path });
					chip.classList.add('done');
				} catch (e) {
					chip.textContent = t('msg.save_failed', { name: att.name });
					chip.disabled = false;
				}
			});
			box.appendChild(chip);
		});
		head.appendChild(box);
	}

	// ── The body ───────────────────────────────────────────
	body.innerHTML = '';
	if (v.html) {
		var bar = document.createElement('div');
		bar.className = 'msg-blocked';
		bar.innerHTML = '<span>' + esc(t('msg.pictures_blocked')) + '</span>';
		var btn = document.createElement('button');
		btn.textContent = t('msg.load_pictures');
		bar.appendChild(btn);

		var frame = document.createElement('iframe');
		frame.className = 'msg-frame';
		// No scripts, and no access to our origin: the message cannot reach the API key in
		// localStorage, the workspace, or this document. Links open in a new tab.
		frame.setAttribute('sandbox', 'allow-popups allow-popups-to-escape-sandbox');
		frame.setAttribute('referrerpolicy', 'no-referrer');

		// The policy is the second wall. The first is the HTML itself: with pictures off it
		// names nothing remote (fe2o3_mail's MessageView), since Firefox's preload fetches a
		// `srcset` before a `<meta>` policy applies. An embedded picture is a `data:` URL.
		function paint(withPictures, html) {
			var csp = withPictures
				? "default-src 'none'; img-src https: data: cid:; style-src 'unsafe-inline'; font-src data:"
				: "default-src 'none'; img-src data:; style-src 'unsafe-inline'; font-src data:";
			frame.srcdoc =
				'<!doctype html><html><head><meta charset="utf-8">'
				+ '<meta http-equiv="Content-Security-Policy" content="' + csp + '">'
				+ '<base target="_blank">'
				+ '<style>html,body{margin:0;padding:14px 16px;background:#fff;color:#111;'
				+ 'font:14px/1.55 system-ui,-apple-system,Segoe UI,sans-serif;'
				+ 'word-break:break-word;overflow-wrap:anywhere}'
				+ 'img{max-width:100%;height:auto}table{max-width:100%}'
				+ 'a{color:#0b57d0}</style></head><body>' + html + '</body></html>';
		}
		// "Load pictures" asks for the message again with its remote pictures named.
		btn.addEventListener('click', function () {
			paint(true, typeof v.withPictures === 'function' ? v.withPictures() : v.html);
			bar.remove();
		});
		paint(false, v.html);

		body.appendChild(bar);
		body.appendChild(frame);
	} else {
		var pre = document.createElement('div');
		pre.className = 'msg-text';
		pre.textContent = v.text || t('msg.no_text');
		body.appendChild(pre);
	}

	DaimondPanels.show('msg');
	DaimondPanels.reflow();
}

// ── Compose: one panel, its buttons bound once ──────────────────
//
// The four buttons are bound at boot and read `composeCur`, the draft on show. They used to be cloned and
// bound afresh on every showing, so a panel shown with no draft (a restored layout, the dead-controls crawl)
// held four buttons with no handler at all, and a draft closed by Send or Discard left its handlers behind.
// Each now answers: with no draft open it is aria-disabled and a press says so; Send also waits for an address.
var composeCur = null;		// the draft on show: { v, atts, paint }, or null when none is open
var composeCtl = [];		// Send, Save Draft, Attach, Discard

function composeSay(msg, bad) {
	var n = document.getElementById('compose-note');
	if (!n) return;
	DaimondI18n.fillPrices(n, msg);
	n.className = 'compose-note' + (bad ? ' err' : '');
}
function composeSync() { composeCtl.forEach(function (c) { c.sync(); }); }
function composeHold(on) { composeCtl.forEach(function (c) { c.hold(on); }); }
function composeFields() {
	var g = function (id) { return document.getElementById(id).value; };
	return { from: g('compose-from'), to: g('compose-to'), cc: g('compose-cc'), subject: g('compose-subject'),
		body: g('compose-text'), attachments: composeCur ? composeCur.atts : [] };
}
// The draft is finished with: let go of it, shut the panel, and have the buttons say none is open.
function composeClose() {
	composeCur = null;
	composeSync();
	DaimondPanels.hide('compose');
	DaimondPanels.reflow();
}

export function initCompose() {
	var send = document.getElementById('compose-send'), save = document.getElementById('compose-save');
	var attach = document.getElementById('compose-attach'), discard = document.getElementById('compose-discard');
	var file = document.getElementById('compose-file'), to = document.getElementById('compose-to');
	if (!send || !save || !attach || !discard || !file || !to) return;
	var why = function (row) {
		return function () {
			var k = row({ open: !!composeCur, to: to.value });
			return k ? t(k) : '';
		};
	};
	var R = DaimondAnswer.reasons;
	composeCtl = [
		DaimondAnswer.control(send, { can: why(R.send), fields: [to], say: composeSay, act: async function () {
			var cur = composeCur, f = composeFields();
			var ok = await confirmDialog(
				t('compose.send_body', { from: f.from }),
				t('compose.send'), { title: t('compose.send_title'), danger: false });
			if (!ok || composeCur !== cur) return;
			composeHold(true);
			composeSay('Sending…');
			try {
				var j = await cur.v.send(f);
				// The charge is a price tag after the words; its glyph is the separator.
				var cost = j && j.charged_minor ? ' ' + DaimondI18n.priceMarkMinor(j.charged_minor, 'usd') : '';
				composeSay('Sent.' + cost);
				if (cur.v.sent) cur.v.sent('Sent to ' + f.to + '.' + cost);
				composeClose();
			} catch (e) {
				composeSay(friendlyError(e), true);
			} finally {
				composeHold(false);
			}
		} }),
		DaimondAnswer.control(save, { can: why(R.draft), say: composeSay, act: async function () {
			var cur = composeCur;
			composeHold(true);
			try {
				var path = await cur.v.save(composeFields());
				composeSay('Saved to ' + path);
			} catch (e) {
				composeSay(friendlyError(e), true);
			} finally {
				composeHold(false);
			}
		} }),
		DaimondAnswer.control(attach, { can: why(R.draft), say: composeSay, act: function () { file.click(); } }),
		DaimondAnswer.control(discard, { can: why(R.draft), say: composeSay, act: async function () {
			var cur = composeCur;
			var ok = await confirmDialog(t('compose.discard_body'),
				t('compose.discard'), { title: t('compose.discard_title'), danger: true });
			if (!ok || composeCur !== cur) return;
			await cur.v.discard();
			composeClose();
		} }),
	];
	file.addEventListener('change', async function () {
		var cur = composeCur;
		var picked = [].slice.call(file.files || []);
		for (var i = 0; cur && i < picked.length; i++) {
			var f = picked[i];
			var buf = await f.arrayBuffer();
			cur.atts.push({
				name:  f.name,
				type:  f.type || 'application/octet-stream',
				size:  buf.byteLength,
				bytes: new Uint8Array(buf),
			});
		}
		file.value = '';
		if (cur) cur.paint();
	});
}

/// Write a message, on the stage, beside the daimon.
///
/// The panel owns the fields and the attachments; the mail module owns the draft — its
/// `Message-ID`, and the message it answers — and gets both back when the user acts.
/// Nothing here composes a message and nothing here speaks SMTP: it collects what the
/// person typed and hands it over.
///
/// Send is deliberately the one button in Daimond that no agent can reach. A message
/// once sent cannot be recalled, and an agent that has just read the user's mail has
/// read a stranger's words: a `mail_send` tool would be a straight path from a
/// sentence in an inbox to a message in the user's name. So the agent may write a
/// draft into the workspace, and a person presses this.
export function showCompose(v) {
	var d      = v.draft || {};
	var from   = document.getElementById('compose-from');
	var to     = document.getElementById('compose-to');
	var cc     = document.getElementById('compose-cc');
	var subj   = document.getElementById('compose-subject');
	var text   = document.getElementById('compose-text');
	var attBox = document.getElementById('compose-atts');
	var title  = document.getElementById('compose-title');
	if (!from || !to || !text) return;

	var atts = (d.attachments || []).slice();
	composeSay('');

	from.innerHTML = '';
	(v.from || []).forEach(function (addr) {
		var o = document.createElement('option');
		o.value = addr;
		o.textContent = addr;
		if (addr === d.from) o.selected = true;
		from.appendChild(o);
	});
	to.value   = d.to || '';
	cc.value   = d.cc || '';
	subj.value = d.subject || '';
	text.value = d.body || '';
	title.textContent = d.subject
		? t(d.inReplyTo ? 'msg.reply' : 'compose.draft') + ' · ' + d.subject
		: t('compose.new_message');

	function paintAtts() {
		attBox.innerHTML = '';
		atts.forEach(function (att, i) {
			var chip = document.createElement('button');
			chip.className = 'compose-att';
			chip.title = t('compose.remove_attachment');
			chip.textContent = att.name + ' · ' + fmtBytes(att.size) + ' ×';
			chip.addEventListener('click', function () {
				atts.splice(i, 1);
				paintAtts();
			});
			attBox.appendChild(chip);
		});
	}
	paintAtts();

	composeCur = { v: v, atts: atts, paint: paintAtts };
	// The fields were filled by script, which raises no input event: ask the buttons again.
	composeSync();

	DaimondPanels.show('compose');
	DaimondPanels.reflow();
	(d.to ? text : to).focus();
}


export function fmtBytes(n) {
	if (!n) return '0 B';
	var u = ['B', 'KB', 'MB', 'GB'], i = 0;
	while (n >= 1024 && i < u.length - 1) { n /= 1024; i++; }
	return (i === 0 ? n : n.toFixed(1)) + ' ' + u[i];
}

/// Ask for a mailbox. The IMAP host and port are guessed from the address,
/// and both stay editable — a guess is not a fact, and plenty of people
/// read mail at a domain their provider does not own.
export function mailDialog(presets, unreachable) {
	var noteEl = null;
	function apply(address, inputs, note) {
		noteEl = note;
		var at = String(address || '').lastIndexOf('@');
		var dom = at < 0 ? '' : address.slice(at + 1).toLowerCase().trim();
		if (!dom) return;
		if (unreachable[dom]) {
			note.className = 'dlg-note err';
			note.textContent = t(unreachable[dom]);
			return;
		}
		var p = presets[dom];
		note.className = 'dlg-note';
		var set = function (k, val) {
			if (inputs[k] && !inputs[k].dataset.touched) inputs[k].value = String(val);
		};
		if (p) {
			set('host', p.host);
			set('port', p.port);
			// Reading and sending are different servers, so the dialog asks for both and
			// guesses both. A mailbox that could be read but not answered would be half a
			// mail client.
			set('smtpHost', p.smtpHost);
			set('smtpPort', p.smtpPort);
			// The note is provider guidance, from a table in this file — not
			// anything the user or a server said.
			note.innerHTML = p.note ? t(p.note) : '';
		} else {
			note.textContent = t('mail.add.guess', { domain: dom });
			set('host', 'imap.' + dom);
			set('smtpHost', 'smtp.' + dom);
		}
	}
	// In the pane, so the user can ask Daimond which password this wants \u2014 and read
	// the answer \u2014 while the box asking for one is still on screen.
	return DaimondAdmin.form({
		kind:  'form',
		title: t('mail.add.title'),
		message: t('mail.add.lead'),
		okLabel: t('mail.add.ok'),
		fields: [
			{ name: 'address',  label: t('mail.add.address'), placeholder: 'you@example.com',
			  hint: function (v, inputs, note) { apply(v, inputs, note); } },
			{ name: 'password', label: t('mail.add.password'), placeholder: t('mail.add.password_ph'), secret: true,
			  note: t('mail.add.password_hint') },
			{ name: 'host',     label: t('mail.add.imap'),    placeholder: 'imap.example.com' },
			{ name: 'port',     label: t('mail.add.port'),    placeholder: '993', value: '993' },
			{ name: 'smtpHost', label: t('mail.add.smtp'),    placeholder: 'smtp.example.com' },
			{ name: 'smtpPort', label: t('mail.add.port'),    placeholder: '587', value: '587' },
		],
		onInit: function (inputs, note) {
			noteEl = note;
			['host', 'port', 'smtpHost', 'smtpPort'].forEach(function (k) {
				if (inputs[k]) inputs[k].addEventListener('input', function () {
					inputs[k].dataset.touched = '1';
				});
			});
		},
		validate: function (v) {
			if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.address)) return t('mail.add.err_address');
			var dom = v.address.slice(v.address.lastIndexOf('@') + 1).toLowerCase();
			if (unreachable[dom]) return t(unreachable[dom]);
			if (!v.password) return t('mail.add.err_password');
			if (!v.host) return t('mail.add.err_imap');
			var p = parseInt(v.port, 10);
			if (p !== 993 && p !== 143) return t('mail.add.err_port');
			v.port = p;
			if (!v.smtpHost) return t('mail.add.err_smtp');
			var s = parseInt(v.smtpPort, 10);
			if (s !== 587 && s !== 465) return t('mail.add.err_smtp_port');
			v.smtpPort = s;
			return '';
		},
	});
}
// page-split: install 111

/// The `.typ` the live view is following, when that is the document `pdf` was
/// just compiled from. Empty when the live view is idle, or is following
/// something else.
///
/// Tied to THIS document rather than to "a watch is running anywhere": the loop
/// may still be following the last file for a moment, and renaming this header
/// after that one would put a second wrong name where the first was.
/// The `.typ` the live view is following, or '' when nothing is.
export function watchedPath() {
	try {
		var w = window.DaimondTypstWatch;
		var st = w ? w.state() : null;
		return (st && st.path) ? st.path : '';
	} catch (e) { return ''; }         // no live view is the ordinary case
}

function liveSource(pdf) {
	try {
		var w = window.DaimondTypstWatch;
		var st = w ? w.state() : null;
		if (!st || st.mode === 'idle' || !st.path) return '';
		return st.path.replace(/\.typ$/i, '.pdf') === pdf ? st.path : '';
	} catch (e) { return ''; }         // no live view is the ordinary case
}

/// Show a compiled PDF on the stage, beside the chat AND beside its source.
///
/// It used to render inside the ~260px Workspace panel, where a page's body
/// text is about three pixels tall, while the widest panel in the app sat
/// empty. Compiling a chapter and then reading it is the whole point of the
/// Typst loop, so the document goes where there is room to read it — and now
/// with the daimon still beside it, to be asked about what it says.
///
/// The pages go to the PREVIEW panel, which is what makes the loop the shape it
/// was built for: the `.typ` stays open in the Doc panel, the pages rebuild
/// beside it on every save, and neither has to take a turn at the other's panel.
export function showDoc(name, url) {
	var e = document.getElementById('doc-embed');
	var n = document.getElementById('pv-name');
	var v = document.getElementById('pv-view');
	if (!e || !n) return;
	// The preview's other rendering steps aside — a file the viewer had drawn
	// here — rather than being torn down, since one panel still shows one thing.
	// It is no longer the TEXT view that steps aside: that is a different panel
	// now, and the file it holds is very often the source of these very pages.
	//
	// Through the Workspace panel's own door, because the viewer's hold on that
	// element is ITS bookkeeping. Reaching in from here and clearing the variable
	// directly was tried: `pvFile` lives in that module's closure, so the compile
	// threw "pvFile is not defined" and the pages were laid out into a panel
	// nothing ever opened.
	if (v) Files.previewAside();
	// ── NOTHING GOES IN THE `<embed>` ON A PHONE ──────────────────────────
	//
	// iOS Safari draws an embedded PDF as PAGE ONE and nothing else: no scroll,
	// no page two, no way to reach the rest of the document. A 48-page book
	// compiled on the phone therefore ARRIVED as one page, and the reader had no
	// way of knowing the other forty-seven were in the file. The live typeset
	// pages are the only rendering that works there — they are drawn here, as
	// SVG, a band at a time — and a `.typ` compiled from this panel always arms
	// them (`began`, called by the Rust compile door), so there is a rendering to
	// route to rather than a gap to leave.
	//
	// `isPhone` and not `isMobileDevice`: this is about the room on screen and
	// about which shell is running, and a desktop window narrowed to a phone's
	// width runs the phone's shell.
	var narrow = !!(window.DaimondShell && DaimondShell.isPhone());
	if (narrow) {
		e.removeAttribute('src');
		e.style.display = 'none';
	} else {
		e.style.display = '';
		e.src = url;
	}
	// THE HEADER NAMES THE FILE THE READER IS EDITING, NOT THE ONE THAT FELL OUT
	// OF COMPILING IT. Pressing ⚙ Compile leaves the pages on screen and rebuilds
	// them from the `.typ` on every save, so a header reading `proj/main.pdf`
	// over pages laid out from `proj/main.typ` names a file nobody is looking at.
	//
	// SPLITTING THE PREVIEW OUT DID NOT MAKE THIS UNNECESSARY, which was worth
	// checking rather than assuming: the reason was never "there is nowhere else
	// to name the source". It is that a header must name what is UNDER it, and
	// while the live view is standing what is under it is a layout of the source,
	// which the PDF on disk may already be behind. Both panels then read
	// `proj/main.typ`, and that is the truth about both: the source, and the
	// source typeset. The PDF is still written, and the line under the Compile
	// button still says where and how big — which is where a by-product belongs.
	pg._docPdf = name;
	n.textContent = liveSource(name) || name;
	DaimondPanels.markUsed('preview');   // it now has something to hold
	DaimondPanels.show('preview');
	DaimondPanels.reflow();
	// On a phone the Preview is a FACE of the Doc sheet rather than a sheet of
	// its own, so "show the preview" means "turn to the Pages tab". `show` above
	// already routes there through `mshow`; this covers the case where the sheet
	// was already up on Source and the engine therefore had nothing to open.
	try {
		if (narrow && window.DaimondSheet && DaimondSheet.isOpen()) DaimondSheet.tab('preview');
	} catch (e2) { /* no sheet at this width */ }
}

/// Ask the header again what the Doc panel is holding.
///
/// Called when the panel is REOPENED, because the live view can let go while it
/// is shut: closing the panel is what ends the watch, and the `<embed>` the live
/// pages stood in for comes back with the PDF in it. A header still naming the
/// source would then be pointing at a file the reader is no longer looking at —
/// and at one the embed need not even match, since the loop may have rebuilt the
/// pages from later edits than the press that wrote the PDF.
///
/// It says nothing when the embed does not have the panel's turn: the live view
/// and the text view each name their own document, and this must not overwrite
/// either.
export function retitleDoc() {
	var n = document.getElementById('pv-name');
	var e = document.getElementById('doc-embed');
	if (!n || !e || !pg._docPdf || e.style.display === 'none') return;
	n.textContent = liveSource(pg._docPdf) || pg._docPdf;
}

/// Create a Diamond, on a model the user chose.
///
/// A Diamond runs the conductor and the reducer -- it thinks, and it is billed for thinking --
/// so which model it runs is as much a decision as it is for a chat. It used to be no decision
/// at all: a Diamond silently took whichever model happened to be starred, and starring a
/// different one later moved every Diamond onto it.
export async function createDiamond() {
	var d = window.DaimondModels ? DaimondModels.getDefault() : { provider: '', model: '' };
	var vals = await dialog({
		kind: 'form',
		title: t('rail.new_diamond'),
		okLabel: t('rail.create'),
		fields: [
			// EMPTY, with the question as its placeholder (CRY-14). It used to
			// open pre-filled with "diamond-0007", which is a name nobody chose
			// and which a person accepts because it is already there -- and a
			// rail of numbered Diamonds is a rail nobody can read. The number is
			// still the answer for somebody who leaves it blank, taken below;
			// what changed is that it stopped being the SUGGESTION.
			{ name: 'name',  label: t('rail.name'), value: '',
				placeholder: t('rail.name_hint') },
			{ name: 'model', label: t('rail.model'), kind: 'models', provider: d.provider, value: d.model },
			// BEHIND THE DISCLOSURE (CRY-14). It is a second decision about money
			// -- this Diamond's daimon dispatches workers and a fan-out is several
			// turns at once -- but it is not one anybody takes at creation, and two
			// model pulldowns in a dialog that exists to name a thing is the dialog
			// asking its least important question at the same rank as its first.
			{ name: 'workerModel', label: t('rail.worker_model'), kind: 'models',
				advanced: true,
				title: t('rail.worker_model_help'), provider: d.provider, value: d.model },
		],
		// The worker pulldown follows the Diamond's own model until the user moves it
		// themselves, so "defaults to the Diamond's model" holds while the dialog is still
		// being filled in rather than only at the instant it opened.
		onInit: function (inputs) {
			var m = inputs.model, w = inputs.workerModel;
			if (!m || !w) return;
			w.addEventListener('change', function () { w._chosen = true; });
			m.addEventListener('change', function () {
				if (w._chosen) return;
				var p = DaimondModels.pick(m);
				DaimondModels.fillSelect(w, p.provider || '', p.model || '');
			});
		},
		validate: function (v) {
			// NO name check: blank is legal and takes the sequential default
			// below. `rail.err_name` stays for the rename paths, which do have
			// to refuse an empty answer -- there is nothing to fall back to.
			// A model is no longer required: none, or the default, follows the default
			// (U1c). Refused only when nothing can run.
			var m = v.model || {};
			if (!DaimondModels.resolve(m.provider || '', m.model || '')) {
				return t(m.model ? 'rail.err_no_key' : 'rail.err_model');
			}
			// A worker model on a provider with no readable key would fall back to the
			// Diamond's own model at dispatch and silently ignore what was chosen here.
			if (v.workerModel && v.workerModel.model
				&& !DaimondModels.resolve(v.workerModel.provider, v.workerModel.model)) {
				return t('rail.err_no_key_worker');
			}
			return '';
		},
	});
	if (!vals) return;
	// The sequential name is the FALLBACK now, not the offer: somebody who
	// had no word in mind still gets a Diamond with a name on it, and the
	// counter is still only burned once one really exists (`takeDiamondLabel`).
	var name = vals.name.trim() || peekDiamondLabel();

	var id;
	try {
		// create_diamond is a pure OPFS write -- no model is consulted -- so any instance will
		// do. The model matters from the Diamond's first *thought*, which is why it is recorded
		// against the Diamond rather than handed to this call.
		id = await diamondApp().create_diamond(name);
		takeDiamondLabel();
	} catch (e) {
		noticeDialog(t('rail.create_failed'), friendlyError(e));
		return;
	}
	// Only a deliberate pick is stored (U1c): an untouched picker, or one left on the
	// default, writes no model, and workers equal to the daimon's model follow it.
	var vm  = vals.model || {};
	var own = storedPick(vm, DaimondModels.getDefault());
	var daimon = DaimondModels.resolve(vm.provider || '', vm.model || '') || own;
	var wk  = storedPick(vals.workerModel, daimon);
	setDiamondModel(id, {
		provider:       own.provider,
		model:          own.model,
		workerProvider: wk.provider,
		workerModel:    wk.model,
	});
	bumpDiamonds();
	// Creating something is the user saying "show me this now". A search
	// string or a tag filter left over from a moment ago can hide the new
	// Diamond behind "No Diamonds match", which reads exactly like the
	// create having done nothing -- so the rail is cleared to show it.
	clearDiamondFilters();
	await loadDiamonds();
	// How many exist now, read off the list that has just been reloaded --
	// which is why it is here and not beside the `create_diamond` above,
	// where the count would have had to be gone and asked for.
	//
	// THIS PATH ONLY, which is the dialog a person filled in. The other
	// callers of `create_diamond` are seeds on a first run and restores from
	// a backup, and counting those would answer "do people build a workspace
	// of their own" with the app's own furniture.
	tel('diamond.new', pg.diamonds.length);
	var f = pg.diamonds.find(function (x) { return x.id === id; });
	if (f) { selectDiamond(f); }
	else {
		// The store took the write and then would not read it back. That is
		// storage trouble, not a no-op, and saying nothing is how a user comes
		// to believe their Diamond vanished and makes it again.
		noticeDialog(t('rail.created_unreadable'),
			t('rail.created_unreadable_body', { name: name }));
	}
	if (isMobile()) mshow('ai');
}

/// Put the rail's tag filter and its search down. Nothing is remembered: a
/// filter is a way of looking, not a setting.
export function clearDiamondFilters() {
	pg.tagInc = [];
	pg.tagExc = [];
	setDiamondQuery('');
}

/// Set the rail's search, field and state together.
export function setDiamondQuery(v) {
	pg.diamondQuery = v.trim().toLowerCase();
	if (diamondSearch && diamondSearch.value !== v) diamondSearch.value = v;
}

export async function selectDiamond(f, view) {
	// The Diamond being left has its page's saves recorded now (D-20261009-29 item 5).
	if (pg.currentDiamond && pg.currentDiamond.id && (!f || f.id !== pg.currentDiamond.id)
		&& window.DaimondVersions && DaimondVersions.flush) {
		DaimondVersions.flush(pg.currentDiamond.id);
	}
	// A menu up was bound to the view being left (OWNKEY-PG).
	DaimondLayers.leave();
	// Before anything moves `current`, and once for both faces: they share the
	// composer, so a draft belongs to the Diamond and not to the face. See
	// `moveComposerTo`.
	moveComposerTo(daimonChat(f));
	pg.currentDiamond = f;
	signalDiamondChanged();
	updateActiveDiamond();
	sessionNameEl.textContent = f.name;
	setDiamondWhen(f);
	var want = (view === 'chat' || view === 'crystal') ? view : diamondView(f.id);
	if (view) setDiamondView(f.id, want);
	// Remembered so this tab's next boot comes back here, on this face. See TAB_VIEW_KEY.
	tabViewSet({ diamond: f && f.id ? f.id : '', chat: '', face: want });
	// The panels this Diamond was worked in, and anything its daimon showed while
	// the person was elsewhere, come back through `followConversation`, which
	// `signalDiamondChanged` above has already run (UNBLOCK-14).

	if (want === 'chat') {
		// `current` IS the daimon's record here, and that is the point: every
		// machinery the thread has — the renderer, the queue, the interject box,
		// the copy control, `_generating` — reads `current`, and pointing it at the
		// daimon's conversation is what makes all of it work without a second copy.
		// The turn itself still goes through `steer_crystal`, because a daimon's
		// tools and fence are not a chat's; `sendUserMessage` is where the two part.
		var rec = daimonChat(f);
		setCurrent(rec);
		pg.curAsstDiv = null; pg.curAsstText = ''; pg.lastToolBlock = null;
		updateActiveSession();
		showCentre('daimon');
		renderHistory(rec.messages);
		// The daimon's transcript loads on open, exactly as a chat's does (seq 213,
		// Stage 1); re-render when the row lands, if this daimon is still on screen.
		if (!rec._loaded) {
			loadChatMessages(rec).then(function () {
				if (pg.current === rec && !rec._generating) renderHistory(rec.messages);
				// See the matching note in `selectChat`: the transcript just
				// landed, so re-run the gate now that `threadStarted` has real
				// turns (or genuinely none) to read rather than a bare summary.
				if (pg.current === rec) syncAttachPrefix();
			}).catch(function () { /* loadMessages never throws */ });
		}
		// A thread with nothing in it reads as a thing that is broken rather than
		// a thing that has not started. Say which -- and say what the two faces
		// are FOR, since this is the moment somebody has just found the second one.
		if (!rec.messages.length) {
			// One blank per thread. `renderHistory` on an empty transcript takes
			// the identical-transcripts early return and clears nothing, so an
			// unguarded append here would stack a fresh "No conversation yet"
			// under the last on every visit to this face. The old blank, if any,
			// is this face's own -- take it and keep one.
			var prev = chatOutput.querySelector('.chat-msg-empty');
			if (prev) prev.remove();
			var blank = document.createElement('div');
			blank.className = 'chat-msg chat-msg-empty';
			blank.textContent = t('crystal.chat_empty');
			chatOutput.appendChild(blank);
		}
		syncComposer();
		renderChatAttachments();          // the chat footer never applies to a Diamond
		syncAttachPrefix();       // the first message's note -- see ATTACH_CONTRACT.md §6
		// Anything left queued on this daimon is drawn again -- `renderHistory` has
		// just rebuilt the thread it lives in -- and then acted on, one tick later
		// so this function finishes drawing before a turn starts writing into it.
		// The chat face's own pair, for the chat face's own reasons; see
		// `selectChat`.
		renderQueue();
		setTimeout(function () { resumeSteerQueue(rec, f.id); }, 0);
		return;
	}
	// `current` is the daimon's own conversation on BOTH faces, because both
	// share the composer and the composer sends to `current`. It used to be
	// nulled here on the reading that "a Diamond's crystal is not a chat" --
	// true of what is DISPLAYED, and false of what the box at the bottom
	// talks to. The thread stays hidden; only the destination is set.
	var crec = daimonChat(f);
	setCurrent(crec);
	updateActiveSession();
	showCentre('focus');
	syncComposer();
	renderChatAttachments();
	syncAttachPrefix();
	// And on the crystal face too: the composer is the same box talking to the
	// same daimon, so a queue left behind is picked up from whichever face the
	// user comes back on. The thread it draws into is hidden here, which costs a
	// few nodes nobody sees and keeps one code path for both faces.
	renderQueue();
	setTimeout(function () { resumeSteerQueue(crec, f.id); }, 0);
	// Folds commit directly (owner decision 2026-09-04), so there is never a
	// pending proposal to restore — the crystal on screen is always the real one.
	await renderCrystal();
}

export function install() { // page-split: install
	// page-split: install 108
	/* var */ agentPinScrollTo = '';
	// page-split: install 109
	/* var */ agentDotFrame = 0;
	// page-split: install 110
	/// Fold again whenever the strip or a chip changes size: the drawer opening (a closed
	/// drawer measures 0), a turn of the phone, a theme with other chip padding.
	/* var */ tagFoldRo = window.ResizeObserver ? new ResizeObserver(function (es) {
		var seen = new Set();
		es.forEach(function (e) {
			var s = e.target.classList.contains('session-box-tags') ? e.target : e.target.parentElement;
			if (s && !seen.has(s)) { seen.add(s); foldTags(s); }
		});
	}) : null;
	// page-split: install 111

	/// The PDF the Doc panel last put in its `<embed>`, so the header can be asked
	/// again later what it should be saying.
	/* var */ pg._docPdf = '';
} // page-split: end install
